_SSO_LOGIN_TIMEOUT = 300
_SSO_CALLBACK_READ_TIMEOUT = 5
# 登录超时/取消后，浏览器里可能还停留着指向本端口的旧登录页（迟到的
# ED 回调稍后才会送达）。立即关端口会让它秒变空白的 connection
# refused；改为保留这么久再真正释放，量级与 _SSO_LOGIN_TIMEOUT 相同，
# 兼顾「接住旧页」与「不长期占用 socket 资源」。
_SSO_EXPIRED_PORT_RETENTION = 300
# expired loopback server 注册表数量上限（Fix G，对应 Codex 二审 C3）：
# 连续取消/重试无上限会不断累积「保留期内」的 socket 与线程；实测一次
# 会话就产生 3 个死端口，量级相当，超限时立即关最旧的一个。
_SSO_EXPIRED_SERVER_MAX = 3
_LOGOUT_LOCK_TIMEOUT = 15
_SSO_REFRESH_LIFETIME = 90 * 24 * 3600
_BACKEND_READY_TIMEOUT = 300
_DESKTOP_SESSION_ATTEMPTS = 3
_DESKTOP_SESSION_RETRY_DELAY = 0.2
_DESKTOP_SESSION_TIMEOUT = 2
_DESKTOP_STATIC_ORIGIN_ENV = "EAZYBOT_DESKTOP_STATIC_ORIGIN"
_TEAM_SWITCH_ENABLED_ENV = "EAZYBOT_TEAM_SWITCH_ENABLED"
# 候选后端激活单独放宽：`/api/desktop/activate` 那头要 await
# `multi_agent_manager.activate_external_consumers()`，即 asyncio.gather 起所有
# 工作区的外部消费者（渠道 / 调度 / MCP，全是网络型），实测超过 2 秒。用会话级的
# 2 秒去等它，必然 timeout_error → 候选激活失败 → 整个 v2 操作失败 → 熔断器
# `trip()` 永久跳闸 → 该进程之后每次切换都静默降级顺序模式（实测 16:39:31
# PREPARE 完成、16:39:34 报 `候选后端激活失败: reason=timeout_error`）。
# 取 30s 与 `_DESKTOP_HANDOFF_TTL_SECONDS` 同量级：激活本身有后端侧的
# `_activation_lock` + `asyncio.shield` 保证不重入，这里只是别过早放弃等待。
_DESKTOP_ACTIVATE_TIMEOUT = 30
_DESKTOP_HANDOFF_TTL_SECONDS = 30
_MAX_CONSUMED_MILESTONE_PROOFS = 4096
