def _environment_enabled(value: str | None) -> bool:
    """只接受常见真值，未知配置安全关闭实验性桌面优化。"""
    return isinstance(value, str) and value.strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }


def _append_cors_origin(existing: str | None, origin: str) -> str:
    """保留已有白名单，并仅追加壳自身的稳定 loopback origin。"""
    origins = [
        item.strip()
        for item in (existing or "").split(",")
        if item.strip()
    ]
    if origin not in origins:
        origins.append(origin)
    return ",".join(origins)


class ProfileIdentityMismatchError(RuntimeError):
    """登录 token 的用户与目标 Profile 不一致。"""

    def __init__(self) -> None:
        super().__init__("登录身份与当前 Profile 不一致，请重新登录")


class ModelKeyAuthorizationError(RuntimeError):
    """ED 拒绝为当前登录身份提供模型 Key。"""

    def __init__(self, *, refresh_allowed: bool = False) -> None:
        super().__init__("模型服务鉴权失败，请重新登录")
        self.refresh_allowed = refresh_allowed


# ---------------------------------------------------------------------------
# SSO Loopback（RFC 8252）
# ---------------------------------------------------------------------------

# expired 端口收到迟到回调时返回的提示页：纯静态字符串，不拼接任何
# 请求参数（防注入）。不带品牌名、不出现 "SSO"/"token" 等术语。
_SSO_EXPIRED_CALLBACK_HTML = """<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<title>登录已结束</title>
</head>
<body style="font-family: -apple-system, 'Segoe UI', sans-serif; text-align: center; padding-top: 15vh; color: #333;">
<h2>本次登录已结束</h2>
<p>请返回客户端重新发起登录，然后关闭此页面。</p>
</body>
</html>
""".encode("utf-8")


class SSOCallbackHandler(http.server.BaseHTTPRequestHandler):
    """loopback 回调处理器：收一次性 token，校验 state，302 回 ED。"""

    # loopback 登录期间仍可能被本机空闲连接占住 handler；短超时可限制
    # 每条未发送 HTTP 请求的连接所占用的线程与文件描述符生命周期。
    timeout = _SSO_CALLBACK_READ_TIMEOUT

    token_received: threading.Event = threading.Event()
    cancel_event: threading.Event = threading.Event()
    one_time_token: Optional[str] = None
    expected_state: str = ""
    ed_success_url: str = ""

    def do_GET(self) -> None:
        parsed = urllib.parse.urlparse(self.path)
        if parsed.path != "/callback":
            self.send_response(404)
            self.end_headers()
            return

        if getattr(self.server, "ed_login_expired", False):
            # 本次登录早已超时/取消，此端口只是延后关闭以体面接住
            # 浏览器里残留的旧登录页——不解析 query、不做 state 校验、
            # 不消费也不回传 token，更不触碰 expected_state 等跨登录
            # 尝试共享的类变量（它可能已被下一轮登录重置）。
            self._respond_expired()
            return

        params = urllib.parse.parse_qs(parsed.query)
        token = params.get("token", [None])[0]
        error = params.get("error", [None])[0]
        state = params.get("state", [None])[0]

        if token:
            if state != self.expected_state:
                logger.warning("SSO state 不匹配，丢弃 token")
                self._redirect_to_ed(error="state_mismatch")
                return
            SSOCallbackHandler.one_time_token = token
            self.token_received.set()
            self._redirect_to_ed()
        elif error:
            SSOCallbackHandler.one_time_token = None
            self.token_received.set()
            self._redirect_to_ed(error=error)
        else:
            self._redirect_to_ed(error="bad_callback")

    def _redirect_to_ed(self, error: Optional[str] = None) -> None:
        url = self.ed_success_url
        if error:
            sep = "&" if "?" in url else "?"
            url = f"{url}{sep}error={urllib.parse.quote(error)}"
        self.send_response(302)
        self.send_header("Location", url)
        self.end_headers()

    def _respond_expired(self) -> None:
        """expired 端口回一个静态提示页，200，不触发任何登录逻辑。"""
        body = _SSO_EXPIRED_CALLBACK_HTML
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, fmt, *args) -> None:
        pass


def start_loopback_server(
    ed_sso_url: str,
) -> tuple[int, socketserver.TCPServer]:
    """起 loopback HTTP 服务，返回 (端口号, server)。

    每次调用前重置类状态：上次回调残留的 set 状态会让本次 wait()
    立即返回陈旧 token。返回 server 供调用方在结束/取消时 shutdown()。
    """
    SSOCallbackHandler.token_received.clear()
    SSOCallbackHandler.cancel_event.clear()
    SSOCallbackHandler.one_time_token = None
    SSOCallbackHandler.expected_state = ""
    SSOCallbackHandler.ed_success_url = (
        f"{ed_sso_url.rstrip('/')}/api/sso/success"
        f"?app_type={urllib.parse.quote(EAZYBOT_APP_NAME)}"
    )
    server = http.server.ThreadingHTTPServer(
        ("127.0.0.1", 0), SSOCallbackHandler
    )
    # 每个 server 实例自带的过期标记（而非类变量）：不同登录尝试各自
    # 拥有独立 server 对象，标记互不干扰，见 Fix C / R18。
    server.ed_login_expired = False
    port = server.server_address[1]
    threading.Thread(target=server.serve_forever, daemon=True).start()
    logger.info("loopback 服务已启动: 127.0.0.1:%s", port)
    return port, server


# Fix G（对应 Codex 二审 C3）：expired server 注册表，模块级 list +
# 锁即可，不新造类。记录「保留期内、尚未真正关闭」的 (server, timer)
# 二元组，数量超限时立即关最旧的一个，防止连续取消/重试无上限累积
# socket 与线程。
_sso_expired_servers: list[
    tuple[socketserver.TCPServer, threading.Timer]
] = []
_sso_expired_servers_lock = threading.Lock()


def _shutdown_server_quietly(
    server: socketserver.TCPServer,
) -> None:
    """真正释放 socket；不加锁，调用方负责注册表增删。

    兜底吞掉 OSError，避免计时器线程或注册流程抛异常。
    """
    try:
        server.shutdown()
        server.server_close()
    except OSError:
        logger.debug("释放已失效 loopback 端口时出错", exc_info=True)


def _register_expired_server(
    server: socketserver.TCPServer, timer: threading.Timer
) -> None:
    """登记一个已标记 expired、延后关闭的 loopback server（R26）。

    数量超过 ``_SSO_EXPIRED_SERVER_MAX`` 时立即关闭最旧的一个并取消
    其计时器——关闭动作放在锁外执行，避免与 ``_close_expired_server``
    的加锁逻辑发生同线程重入死锁。
    """
    evicted: list[
        tuple[socketserver.TCPServer, threading.Timer]
    ] = []
    with _sso_expired_servers_lock:
        _sso_expired_servers.append((server, timer))
        while len(_sso_expired_servers) > _SSO_EXPIRED_SERVER_MAX:
            evicted.append(_sso_expired_servers.pop(0))
    for old_server, old_timer in evicted:
        old_timer.cancel()
        _shutdown_server_quietly(old_server)


def _close_expired_server(server: socketserver.TCPServer) -> None:
    """保留期结束后真正释放已标记 expired 的 loopback server。

    由 threading.Timer 线程调用（到期正常关闭）；关闭前先从注册表
    移除自身，避免 R26 的存活数计数残留已关闭条目。
    """
    with _sso_expired_servers_lock:
        _sso_expired_servers[:] = [
            (s, t) for s, t in _sso_expired_servers if s is not server
        ]
    _shutdown_server_quietly(server)


# SSO 重登冷却：记录最近一次 SSO 登录成功（收到回调）的时间。
_SSO_RELOGIN_COOLDOWN_SECONDS = 120.0
_last_sso_login_success_ts: float = 0.0


def start_sso_login(ed_sso_url: str) -> Optional[str]:
    """拉起系统浏览器登录，阻塞等待回调。

    返回 one-time token 或 None（超时/取消）。壳应在 worker 线程
    调用本函数（它会阻塞），UI 线程调 cancel_sso_login() 中断。
    """
    port, server = start_loopback_server(ed_sso_url)
    # 仅「超时」「取消」这两种真正可能留下浏览器旧登录页的场景才
    # 延后关端口；成功、以及拉起浏览器直接失败（浏览器根本没打开
    # 过页面）仍沿用原行为，登录结束即刻关闭。
    defer_close = False
    try:
        redirect_uri = f"http://127.0.0.1:{port}/callback"
        state = secrets.token_urlsafe(16)
        SSOCallbackHandler.expected_state = state
        authorize_url = (
            f"{ed_sso_url.rstrip('/')}/api/sso/authorize"
            f"?redirect_uri={urllib.parse.quote(redirect_uri)}"
            f"&state={state}"
        )

        logger.info("打开系统浏览器进行 SSO 登录")
        try:
            opened = webbrowser.open(authorize_url)
        except Exception:
            logger.exception("拉起系统浏览器失败")
            return None
        if not opened:
            logger.warning(
                "webbrowser.open 返回 False，系统浏览器可能未被拉起"
            )

        deadline = time.monotonic() + _SSO_LOGIN_TIMEOUT
        while time.monotonic() < deadline:
            if SSOCallbackHandler.token_received.wait(timeout=0.5):
                break
            if SSOCallbackHandler.cancel_event.is_set():
                break

        if SSOCallbackHandler.cancel_event.is_set():
            logger.info("SSO 登录已取消")
            defer_close = True
            return None
        if not SSOCallbackHandler.token_received.is_set():
            logger.warning(
                "SSO 登录超时（等待 %ds 未收到回调）",
                _SSO_LOGIN_TIMEOUT,
            )
            defer_close = True
            return None
        global _last_sso_login_success_ts
        _last_sso_login_success_ts = time.time()
        return SSOCallbackHandler.one_time_token
    finally:
        if defer_close:
            # 标记 expired 并延后关闭：迟到的回调会被 do_GET 接住并
            # 回一个体面提示页；保留期结束后由计时器（daemon 线程，
            # 不吊住壳进程退出）真正释放端口，见 R15/R16。
            server.ed_login_expired = True
            timer = threading.Timer(
                _SSO_EXPIRED_PORT_RETENTION,
                _close_expired_server,
                args=(server,),
            )
            timer.daemon = True
            try:
                timer.start()
            except RuntimeError:
                # Fix G / R27：计时器线程启动失败（如线程资源耗尽）
                # 不得静默泄漏 socket——立即关闭，不登记进注册表。
                logger.exception(
                    "expired loopback 计时器启动失败，"
                    "立即关闭端口避免泄漏"
                )
                _shutdown_server_quietly(server)
            else:
                _register_expired_server(server, timer)
        else:
            server.shutdown()
            server.server_close()


def cancel_sso_login() -> None:
    """中断 start_sso_login 的等待（壳登录 UI 的"取消"按钮调用）。"""
    SSOCallbackHandler.cancel_event.set()


