def exchange_sso_token(one_time_token: str) -> dict:
    """用一次性 token 换 SSO JWT + 用户信息。

    复用 ``auth._sso_exchange_token`` 逻辑（读取 EAZYDEVELOP_SSO_URL
    env）。返回 ED 完整响应 dict 或 ``{"error": reason}``。
    """
    import asyncio

    return asyncio.run(_sso_exchange_token(one_time_token))


def refresh_sso_token(refresh_token: str) -> Optional[dict]:
    """同步调用 SSO refresh，供启动后端前的模型鉴权自愈使用。"""
    import asyncio

    return asyncio.run(_sso_refresh(refresh_token))


def fetch_org_list(
    access_token: str, ed_api_url: str
) -> list[dict]:
    """用 SSO JWT 调 ED ``/api/org/list`` 拉取用户所属团队列表。"""
    import httpx

    url = f"{ed_api_url.rstrip('/')}/api/org/list"
    t0 = time.perf_counter()
    logger.info("开始拉取 ED 团队列表: url=%s", url)
    resp = httpx.get(
        url,
        headers={"Authorization": f"Bearer {access_token}"},
        timeout=10,
    )
    t1 = time.perf_counter()
    logger.info("ED 团队列表 HTTP 请求完成，耗时 %.2fs，状态码 %d", t1 - t0, resp.status_code)
    resp.raise_for_status()
    data = resp.json()
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        orgs = data.get("data")
        return orgs if isinstance(orgs, list) else []
    return []


def _decrypt_sso_access_token(
    auth_data: dict, secret_dir: Path
) -> str:
    """解密 SSO access token，失败时绝不返回仍加密的密文。"""
    token = decrypt_for_dir(
        auth_data.get("sso_access_token", ""), secret_dir
    )
    if is_encrypted(token):
        logger.warning(
            "sso_access_token 解密失败，已阻止把密文作为 Bearer token 发出"
        )
        return ""
    return token


def _auth_http_status(exc: BaseException) -> Optional[int]:
    """提取 httpx/urllib 风格异常的 HTTP 状态码。"""
    response = getattr(exc, "response", None)
    status_code = getattr(response, "status_code", None)
    if status_code is None:
        status_code = getattr(exc, "code", None)
    return status_code if isinstance(status_code, int) else None


def _is_auth_http_error(exc: BaseException) -> bool:
    """判断 httpx/urllib 风格异常是否为 ED 401/403。"""
    return _auth_http_status(exc) in (401, 403)


