def _profile_dir(app_root: Path, user_id: str, org_id: str) -> Path:
    """返回 profile 工作目录路径。"""
    return app_root / "profiles" / user_id / org_id


def _atomic_write_json(path: Path, data: dict) -> None:
    """原子写入 JSON 文件（temp + rename），权限 0o600。"""
    import tempfile

    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(
        dir=str(path.parent), suffix=".tmp"
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        os.chmod(tmp_name, 0o600)
        os.replace(tmp_name, path)
    except Exception:
        try:
            os.unlink(tmp_name)
        except OSError:
            pass
        raise


def _write_sso_tokens_to_profile(
    profile_dir: Path,
    token_data: dict,
    *,
    revive_logged_out: bool = True,
) -> bool:
    """将 SSO token 数据写入 profile 的 ``.secret/auth.json``。

    写入明文（sso_access_token / sso_refresh_token），后端首次读取
    时自动加密（_load_auth_data 的 plaintext 迁移逻辑）。权限 0o600。

    Fix E：本函数是壳侧当前 profile 登录成功写 token 的唯一
    入口。只有真正登录成功才能摘除
    ``_clear_sso_tokens()`` 写入的登出墓碑（R24）；同账号兄弟
    profile 则由中央同步函数的显式登录模式重新授权。
    """
    secret_dir = profile_dir / ".secret"
    secret_dir.mkdir(parents=True, exist_ok=True)
    auth_file = secret_dir / "auth.json"

    if auth_file.is_file():
        try:
            data = json.loads(
                auth_file.read_text(encoding="utf-8")
            )
        except (OSError, ValueError):
            data = {}
    else:
        data = {}

    # Fix I（Codex 复审 D2）：json.loads 可能返回 list / str / int /
    # None 等非 dict 根节点，直接 .pop / 下标赋值会抛
    # AttributeError / TypeError，导致损坏的 auth.json **重新登录也
    # 修不好**，用户只能手删文件。这里按「损坏内容」重建为空 dict，
    # 让一次正常登录就能自愈。必须排在墓碑闸门之前——对非 dict 调
    # data.get() 同样会抛 AttributeError。
    if not isinstance(data, dict):
        logger.warning(
            "auth.json 根节点不是 dict，按损坏内容重建后写入新 token"
        )
        data = {}

    if (
        data.get(SSO_LOGOUT_TOMBSTONE_FIELD)
        and not revive_logged_out
    ):
        logger.info("Profile 已退出登录，忽略延迟返回的 SSO token")
        return False
    if revive_logged_out:
        data.pop(SSO_LOGOUT_TOMBSTONE_FIELD, None)

    data["sso_access_token"] = token_data.get("access_token", "")
    data["sso_refresh_token"] = token_data.get("refresh_token", "")
    expires_in = token_data.get("expires_in", 0)
    data["sso_access_token_expires_at"] = (
        int(time.time()) + int(expires_in)
    )
    user_info = token_data.get("user") or {}
    if user_info:
        data["sso_user_info"] = user_info

    _atomic_write_json(auth_file, data)
    return True


def _read_sso_tokens_from_profile(
    auth_file: Path,
) -> tuple[dict, str, str]:
    """读取并解密 profile 的 SSO 数据。"""
    with open(auth_file, "r", encoding="utf-8") as handle:
        auth_data = json.load(handle)
    access_token = _decrypt_sso_access_token(
        auth_data, auth_file.parent
    )
    refresh_token = decrypt_for_dir(
        auth_data.get("sso_refresh_token", ""), auth_file.parent
    )
    return auth_data, access_token, refresh_token


def _copy_auth_for_new_profile(
    src_auth: Path,
    dst_auth: Path,
    src_secret_dir: Path,
) -> None:
    """跨 profile 复制 auth.json，敏感字段解密后写明文。

    后端进程以各自 profile 的 ``.secret`` 作为 ``SECRET_DIR`` 加密
    auth.json；直接整文件复制会把源 profile 的密文带到新 profile，
    当 OS keyring 不可用、两 profile 的 master key 不同时，新后端
    解不开 -> 切到未装过的团队必坏（缺口 #14）。这里用源 profile
    的 master key 解密敏感字段、以明文写入目标，新后端首次读取时
    会自动加密（``_load_auth_data`` 的 plaintext 迁移逻辑）。非
    敏感字段原样保留。源文件读不出时回落到整文件复制（不丢数据）。
    """
    try:
        raw = json.loads(
            src_auth.read_text(encoding="utf-8")
        )
    except (json.JSONDecodeError, OSError):
        shutil.copy2(src_auth, dst_auth)
        return

    decrypted = dict(raw)
    for field in AUTH_SECRET_FIELDS:
        val = decrypted.get(field)
        if isinstance(val, str) and val:
            decrypted[field] = decrypt_for_dir(
                val, src_secret_dir
            )
    _atomic_write_json(dst_auth, decrypted)


def _clear_sso_tokens(
    profile_dir: Path, app_root: Optional[Path] = None
) -> None:
    """清除 profile 的 SSO token（退出登录），并写入登出墓碑。

    墓碑 ``SSO_LOGOUT_TOMBSTONE_FIELD`` 用来封死一条竞态：退出登录与
    后端 token 刷新可能交叠，后端 ``_save_sso_tokens`` 是「整读-改-整写」，
    若只靠 ``sso_refresh_token`` 是否为空判断登出，一次迟到的写回就会把
    刚退出的登录状态原样复活。墓碑落盘后，后端与壳两侧都以它为准
    （``app/auth.py`` 已尊重同一常量），判据层面不再有复活窗口。
    """
    if app_root is not None:
        with sso_profile_auth_lock(app_root):
            _clear_sso_tokens(profile_dir)
        return

    auth_file = profile_dir / ".secret" / "auth.json"
    if not auth_file.is_file():
        return
    try:
        data = json.loads(auth_file.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        data = {}

    for key in (
        "sso_access_token",
        "sso_refresh_token",
        "sso_access_token_expires_at",
        "sso_user_info",
    ):
        data.pop(key, None)
    data[SSO_LOGOUT_TOMBSTONE_FIELD] = time.time_ns()

    _atomic_write_json(auth_file, data)


def _symlink_local_models(
    profile_dir: Path, app_root: Path
) -> None:
    """创建 local_models 软链到共享层（零代码改动方案 A）。"""
    shared_models = app_root / "shared" / "local_models"
    shared_models.mkdir(parents=True, exist_ok=True)
    link_path = profile_dir / "local_models"
    if link_path.exists() or link_path.is_symlink():
        return
    try:
        link_path.symlink_to(
            Path("../../../shared/local_models"),
            target_is_directory=True,
        )
    except (OSError, NotImplementedError):
        logger.warning(
            "无法创建 local_models 软链，跳过共享层"
        )


def create_profile(
    profile_store: ProfileStore,
    app_root: Path,
    user_info: dict,
    org_info: dict,
    sso_token_data: Optional[dict] = None,
    source_profile_dir: Optional[Path] = None,
    operation_id: Optional[str] = None,
    activate: bool = True,
) -> str:
    """创建 profile 并写入 SSO token。

    Args:
        profile_store: profile 索引读写器。
        app_root: App 根目录（``~/.{app_name}``）。
        user_info: ED 用户信息（user_id/username/avatar 等）。
        org_info: ED 团队信息（id/org_name/avatar）。
        sso_token_data: ED token 交换响应。首次登录传入；
            其中的用户必须与 ``user_info`` 一致。切团队传 None
            （从 source_profile_dir 复制）。
        source_profile_dir: 切团队时旧 profile 目录（从其
            ``.secret/auth.json`` 复制 SSO token）。
        operation_id: 首次加入团队的候选操作 ID；传入后先写为
            provisioning，直到显式激活。
        activate: 是否立即原子激活。候选后端启动前必须为 False。

    Returns:
        profile_id（``<user_id>/<org_id>``）。
    """
    user_id = user_info["user_id"]
    if sso_token_data:
        token_user = sso_token_data.get("user") or {}
        if token_user.get("user_id") != user_id:
            raise ValueError("SSO token 用户与 profile 用户不一致")
    org_id = org_info["id"]
    pid = ProfileStore.make_profile_id(user_id, org_id)
    p_dir = _profile_dir(app_root, user_id, org_id)

    p_dir.mkdir(parents=True, exist_ok=True)
    (p_dir / ".secret").mkdir(exist_ok=True)
    (p_dir / ".backups").mkdir(exist_ok=True)

    _symlink_local_models(p_dir, app_root)

    if sso_token_data:
        _write_sso_tokens_to_profile(p_dir, sso_token_data)
    elif source_profile_dir is not None:
        src_secret = source_profile_dir / ".secret"
        src_auth = src_secret / "auth.json"
        if src_auth.is_file():
            dst_auth = p_dir / ".secret" / "auth.json"
            _copy_auth_for_new_profile(
                src_auth, dst_auth, src_secret
            )
            os.chmod(dst_auth, 0o600)

    expires_in = (
        int(sso_token_data.get("expires_in", 0))
        if sso_token_data
        else 0
    )
    now = int(time.time())
    access_expires = now + expires_in if expires_in else 0
    refresh_expires = now + _SSO_REFRESH_LIFETIME

    profile_entry = {
        "user_id": user_id,
        "username": user_info.get("username", ""),
        "avatar": user_info.get("avatar", ""),
        "org_id": org_id,
        "org_name": org_info.get("org_name", ""),
        "working_dir": str(p_dir),
        "created_at": time.strftime(
            "%Y-%m-%dT%H:%M:%SZ", time.gmtime()
        ),
        "last_used_at": time.strftime(
            "%Y-%m-%dT%H:%M:%SZ", time.gmtime()
        ),
        "sso": {
            "access_token_expires_at": access_expires,
            "refresh_token_expires_at": refresh_expires,
        },
    }
    if operation_id:
        profile_store.upsert_provisional(profile_entry, operation_id)
    else:
        profile_store.add_profile(profile_entry)
    if sso_token_data:
        try:
            sync_sso_tokens_to_sibling_profiles(
                app_root,
                p_dir / ".secret" / "auth.json",
                sso_token_data,
                encrypt_tokens=False,
                revive_logged_out=True,
            )
        except Exception:
            logger.warning(
                "显式登录后同步兄弟 profile 的 SSO token 失败",
                exc_info=True,
            )
    if activate:
        profile_store.activate_profile(
            pid, operation_id=operation_id
        )

    logger.info("profile 已创建")
    return pid


def delete_profile_entry(
    profile_store: ProfileStore,
    app_root: Path,
    profile_id: str,
) -> None:
    """删除 profile 目录与索引条目。"""
    profile = profile_store.get_profile(profile_id)
    if profile is None:
        return

    p_dir = _profile_dir(
        app_root, profile["user_id"], profile["org_id"]
    )
    if p_dir.exists():
        shutil.rmtree(p_dir, ignore_errors=True)

    # 清兄弟目录 <p_dir>.secret（后端 SECRET_DIR 默认路径，
    # 13.1 落地前的历史残留）
    sibling_secret = p_dir.parent / f"{p_dir.name}.secret"
    if sibling_secret.exists():
        shutil.rmtree(sibling_secret, ignore_errors=True)

    profile_store.remove_profile(profile_id)
    logger.info("profile 已删除")


def cleanup_legacy_data(app_root: Path) -> None:
    """首启迁移后移走老数据，防止后续 profile 重复复制。

    ``config.py:2185-2200`` 的迁移逻辑把 ``~/.eazybot/{sessions,
    memory,jobs.json,AGENTS.md,SOUL.md,PROFILE.md}`` 复制到首个
    profile 的 ``workspaces/default/``，但不删源。本函数把源移到
    ``.migrated/``，确保后续 profile 是干净的空目录。
    """
    migrated_dir = app_root / ".migrated"
    migrated_dir.mkdir(exist_ok=True)

    for item in [
        "sessions",
        "memory",
        "jobs.json",
        "AGENTS.md",
        "SOUL.md",
        "PROFILE.md",
    ]:
        src = app_root / item
        if src.exists():
            dst = migrated_dir / item
            if not dst.exists():
                shutil.move(str(src), str(dst))
                logger.info("老数据已迁移: %s", item)


