def load_env_chain(
    app_root: Path,
    profile_dir: Optional[Path] = None,
) -> dict[str, str]:
    """按优先级加载 .env 链，返回合并后的 env dict。

    加载顺序（后者覆盖前者）：
    1. ``~/.{app_name}/.env``（全局默认）
    2. ``~/.{app_name}/.env.local``（全局覆盖）
    3. ``<profile_dir>/.env``（profile 级）
    4. ``<profile_dir>/.env.local``（profile 覆盖）
    """
    env: dict[str, str] = {}

    paths = [app_root / ".env", app_root / ".env.local"]
    if profile_dir is not None:
        paths.append(profile_dir / ".env")
        paths.append(profile_dir / ".env.local")

    for path in paths:
        if path.is_file():
            values = dotenv_values(path)
            env.update(
                {
                    k: v
                    for k, v in values.items()
                    if v is not None
                }
            )

    return env


def build_backend_env(
    base_env: dict[str, str],
    profile_dir: Path,
    org_id: str,
    app_name: str,
    log_level: str,
    app_root: Optional[Path] = None,
    model_api_key: Optional[str] = None,
    handshake_secret: Optional[str] = None,
    user_id: str = "",
) -> dict[str, str]:
    """构建后端子进程 env：.env 链 + 壳动态覆盖（最高优先级）。"""
    env = dict(base_env)

    env["EAZYBOT_WORKING_DIR"] = str(profile_dir)
    if app_root is not None:
        env["EAZYBOT_APP_ROOT"] = str(app_root)
    env["EAZYDEVELOP_ORG_ID"] = org_id
    if user_id:
        env["EAZYDEVELOP_USER_ID"] = user_id
    env["EAZYBOT_APP_NAME"] = app_name
    env["EAZYBOT_CLIENT_MODE"] = "1"
    env["EAZYBOT_RUNNING_IN_CONTAINER"] = "0"
    env["EAZYBOT_SECRET_DIR"] = str(profile_dir / ".secret")
    env[LOG_LEVEL_ENV] = log_level

    if model_api_key:
        env["EAZYDEVELOP_API_KEY"] = model_api_key

    # 桌面会话交接握手密钥（缺口 #13）：只进子进程 env，不落盘
    if handshake_secret:
        env["EAZYBOT_SHELL_HANDSHAKE_SECRET"] = (
            handshake_secret
        )

    if "EAZYDEVELOP_SSO_URL" not in env:
        logger.warning("EAZYDEVELOP_SSO_URL 未设置")
    if "EAZYDEVELOP_API_BASE_URL" not in env:
        sso_url = env.get("EAZYDEVELOP_SSO_URL", "")
        if sso_url:
            env["EAZYDEVELOP_API_BASE_URL"] = sso_url.rstrip("/")

    return env


