class SingleInstanceLock:
    """App 级单实例锁（per-App 非 per-profile）。

    POSIX 用 ``fcntl.flock``，Windows 用 ``msvcrt.locking``。
    锁文件在 App 根目录 ``.shell.lock``。进程退出时 fd 关闭，
    OS 自动释放锁。
    """

    def __init__(self, app_root: Path):
        self._lock_file = app_root / ".shell.lock"
        self._fd: Optional[int] = None

    def acquire(self) -> bool:
        """尝试获取排他锁。返回 True 成功，False 已被占用。"""
        self._fd = os.open(
            str(self._lock_file),
            os.O_CREAT | os.O_RDWR,
            0o644,
        )
        try:
            if sys.platform == "win32":
                import msvcrt

                msvcrt.locking(self._fd, msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(
                    self._fd,
                    fcntl.LOCK_EX | fcntl.LOCK_NB,
                )
            return True
        except (OSError, IOError):
            os.close(self._fd)
            self._fd = None
            return False

    def release(self) -> None:
        """释放锁。"""
        if self._fd is None:
            return
        try:
            if sys.platform == "win32":
                import msvcrt

                msvcrt.locking(self._fd, msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(self._fd, fcntl.LOCK_UN)
        except (OSError, IOError):
            pass
        finally:
            os.close(self._fd)
            self._fd = None


class DesktopShell:
    """桌面壳状态管理：当前 profile、后端子进程、SSO 登录。

    封装 desktop_cmd 的非 UI 逻辑：SSO loopback 登录、profile 创建/
    切换/删除、env 注入起后端子进程、on_sso_expired/on_logout bridge。
    """

    def __init__(
        self,
        host: str = "127.0.0.1",
        log_level: str = "info",
        app_name: str = EAZYBOT_APP_NAME,
        app_root: Optional[Path] = None,
    ):
        self._host = host
        self._log_level = log_level
        self._app_name = app_name
        self._app_root = app_root or Path(
            f"~/.{app_name}"
        ).expanduser()
        self._app_root.mkdir(parents=True, exist_ok=True)
        self._console_static_server: DesktopConsoleStaticServer | None = None
        if _environment_enabled(os.environ.get(_DESKTOP_STATIC_ORIGIN_ENV)):
            try:
                static_server = DesktopConsoleStaticServer()
                static_server.start()
                self._console_static_server = static_server
            except Exception as exc:
                logger.warning(
                    "桌面 Console 静态服务不可用，回退后端同源导航: reason=%s",
                    safe_exception_reason(exc),
                )
        self._profile_store = ProfileStore(
            self._app_root / "profiles.json"
        )
        self._backend_runtime = DesktopBackendRuntime(
            host=self._host,
            log_level=self._log_level,
            prepare_env=self._prepare_backend_env,
            clock=time.monotonic,
            popen=lambda *args, **kwargs: subprocess.Popen(
                *args, **kwargs
            ),
            port_allocator=lambda host: _find_free_port(host),
            readiness_probe=self._probe_backend_readiness,
            process_tree_controller=ProcessTreeController(
                platform=sys.platform,
                windows_controller=create_default_windows_job_controller(
                    sys.platform
                ),
            ),
            on_exit=self._on_backend_exit,
            platform=sys.platform,
        )
        self._current_profile_id: Optional[str] = None
        # ED 连接探测（09.6）：online / degraded / offline
        self._connection_state: str = "online"
        self._connection_lock = threading.Lock()
        self._ed_probe_thread: Optional[threading.Thread] = None
        # 可中断等待：登录/重登后立即唤醒探测线程重算，
        # 不必等到下一个 interval（见 start_ed_probe）。
        self._ed_probe_wake = threading.Event()
        # 切换/删除操作锁（14.1：拒绝重入 + 失败信号载体）
        self._switch_lock = threading.RLock()
        self._switch_state: str = "idle"  # idle / switching / success / failed / busy
        self._switch_error: str = ""
        # 自增序号：每次操作入口 +1，前端比对 seq 判断状态是否属于本次操作，
        # 彻底解决终态（success/failed/busy）永不复位导致的陈旧状态误判。
        self._switch_seq: int = 0
        # 看门狗重启后通知壳层 load_url（15.2）
        self.on_backend_restarted = None
        # 12.2：SSO 登录流程中间状态（供 bridge 轮询）
        self._login_state: str = "idle"  # idle/logging_in/success/failed/multi_org
        self._login_error: str = ""
        self._login_seq: int = 0
        self._pending_orgs: list = []
        self._pending_token_data: dict | None = None
        self._pending_user_info: dict | None = None
        self._pending_ed_sso_url: str = ""
        self._pending_ed_api_url: str = ""
        # 退出登录优先：长操作提交凭据或激活 profile 前必须比对该代数。
        self._logout_epoch = 0
        self._backend_start_lock = threading.Lock()
        self._backend_start_cancellations: set[threading.Event] = set()
        # 团队归属快照只存内存，按 ED URL + 原样 user_id 隔离。
        self._org_snapshot_cache = OrgSnapshotCache()
        self._org_cache_context_key: OrgCacheKey | None = None
        self._org_cache_context_lock = threading.Lock()
        # 运行期团队切换独立于双槽算法开关，默认安全关闭。壳启动后固定，
        # 避免一次会话内前端入口与写操作边界看到不同配置。
        self._team_switch_enabled = _environment_enabled(
            os.environ.get(_TEAM_SWITCH_ENABLED_ENV)
        )
        # v2 部署模式只在 Shell 启动时读取，之后每次操作只读内存策略。
        deployment_mode = TeamSwitchPolicy.mode_from_environment(
            os.environ.get("EAZYBOT_TEAM_SWITCH_MODE")
        )
        self._team_switch_policy = TeamSwitchPolicy(deployment_mode)
        self._team_switch_metrics = LocalTeamSwitchMetrics()
        self._v2_timing_lock = threading.Lock()
        self._v2_timing_starts: dict[
            tuple[str, int], tuple[float, float, float]
        ] = {}
        self._team_switch_contexts: dict[
            tuple[str, int], dict[str, Any]
        ] = {}
        self._team_switch_context_lock = threading.Lock()
        self._milestone_proof_lock = threading.Lock()
        self._consumed_milestone_proofs: dict[str, int] = {}
        self._accepted_v2_operations: set[tuple[str, int]] = set()
        self._operation_state_lock = threading.Lock()
        self._legacy_operation_depth: dict[int, int] = {}
        self._v2_operation_identity: tuple[str, int] | None = None
        self._team_switch_navigator: Callable[[str], None] | None = None
        self._runtime_registry = DesktopRuntimeRegistry(
            self._app_root / ".desktop-runtime.json"
        )
        self._shell_started_at = time.time()
        self._lease_id = secrets.token_hex(16)
        self._lease_heartbeat_stop = threading.Event()
        self._lease_heartbeat_thread: threading.Thread | None = None
        self._lease_heartbeat_lock = threading.Lock()
        self._lease_heartbeat_namespace = ""
        self._team_switch_coordinator = TeamSwitchCoordinator(
            profile_store=self._profile_store,
            runtime=self._backend_runtime,
            target_resolver=self._resolve_team_switch_target,
            proof_verifier=self._verify_team_switch_proof,
            navigate=self._navigate_team_switch_candidate,
            recover=self._recover_team_switch,
            on_old_retired=self._activate_promoted_candidate,
            generation_factory=self._backend_runtime.next_generation,
        )

    @property
    def profile_store(self) -> ProfileStore:
        return self._profile_store

    @property
    def org_snapshot_cache(self) -> OrgSnapshotCache:
        """返回 Shell 级团队快照缓存。"""
        return self._org_snapshot_cache

    @property
    def backend_runtime(self) -> DesktopBackendRuntime:
        """返回桌面后端唯一进程真相源。"""
        return self._backend_runtime

    @property
    def current_profile_id(self) -> Optional[str]:
        return self._current_profile_id

    @property
    def backend_url(self) -> Optional[str]:
        slot = self._backend_runtime.active_slot
        if slot is None:
            return None
        return f"http://{self._host}:{slot.port}"

    @property
    def _backend_proc(self) -> Optional[subprocess.Popen]:
        """旧私有读取兼容：值始终来自 Runtime active snapshot。"""
        slot = self._backend_runtime.active_slot
        return slot.process if slot is not None else None

    @property
    def _backend_port(self) -> Optional[int]:
        """旧私有读取兼容：不维护第二份端口状态。"""
        slot = self._backend_runtime.active_slot
        return slot.port if slot is not None else None

    @property
    def _handshake_secret(self) -> Optional[str]:
        """旧私有读取兼容：secret 归 active slot 所有。"""
        slot = self._backend_runtime.active_slot
        return slot.handshake_secret if slot is not None else None

    def set_team_switch_navigator(
        self,
        navigator: Callable[[str], None] | None,
    ) -> None:
        """由 UI 层注册唯一页面导航副作用。"""
        self._team_switch_navigator = navigator

    def get_capabilities(self) -> dict[str, Any]:
        """返回不含环境或凭据的桌面协议能力。"""
        mode = self._team_switch_policy.resolve_mode()
        return {
            "protocol_version": 2,
            "team_switch_enabled": self._team_switch_enabled,
            "team_switch_v2": True,
            "team_switch_mode": mode.value,
            "double_slot_enabled": mode is TeamSwitchMode.DOUBLE_SLOT,
            "telemetry_upload_enabled": False,
            "rollout_eligible": self._team_switch_metrics.rollout_eligible,
        }

    def begin_team_switch(
        self,
        *,
        kind: str,
        target_id: str,
        operation_id: str,
        click_to_overlay_ms: float,
        click_to_bridge_ms: float,
    ) -> dict[str, Any]:
        """立即接受 v2 请求；实际准备在 Coordinator worker 中执行。"""
        if not self._team_switch_enabled:
            return asdict(
                BeginResult(
                    False,
                    operation_id if isinstance(operation_id, str) else "",
                    0,
                    TeamSwitchMode.SEQUENTIAL.value,
                    "feature_disabled",
                )
            )
        self._refresh_team_switch_policy()
        mode = self._team_switch_policy.resolve_mode()
        if mode is not TeamSwitchMode.DOUBLE_SLOT:
            return asdict(
                BeginResult(
                    False,
                    operation_id if isinstance(operation_id, str) else "",
                    0,
                    TeamSwitchMode.SEQUENTIAL.value,
                    "sequential_mode",
                )
            )
        if kind not in {"switch", "join", "recover_active"}:
            return asdict(
                BeginResult(
                    False,
                    operation_id if isinstance(operation_id, str) else "",
                    0,
                    mode.value,
                    "invalid_kind",
                )
            )
        if not self._claim_v2_operation(operation_id):
            return asdict(
                BeginResult(
                    False,
                    operation_id if isinstance(operation_id, str) else "",
                    0,
                    mode.value,
                    "operation_busy",
                )
            )
        started_at = time.monotonic()
        try:
            result = self._team_switch_coordinator.begin(
                target_id,
                operation_id,
                kind,
            )
        except BaseException:
            self._release_v2_operation()
            raise
        if result.accepted:
            identity = (result.operation_id, result.generation)
            with self._operation_state_lock:
                self._accepted_v2_operations.add(identity)
                self._v2_operation_identity = identity
            with self._v2_timing_lock:
                self._v2_timing_starts[identity] = (
                    started_at,
                    click_to_overlay_ms,
                    click_to_bridge_ms,
                )
            self._record_v2_timing(
                identity,
                stage="bridge_received",
                result="success",
            )
        else:
            self._release_v2_operation()
        self._team_switch_metrics.record(
            stage="accepted",
            result="success" if result.accepted else "failed",
            duration_ms=(time.monotonic() - started_at) * 1000,
            error_code=None if result.accepted else "unknown",
            operation_id=operation_id,
            target_id=target_id,
            click_to_overlay_ms=click_to_overlay_ms,
            click_to_bridge_ms=click_to_bridge_ms,
        )
        return asdict(result)

    def get_team_switch_operation(
        self,
        operation_id: str,
        generation: int,
    ) -> dict[str, Any]:
        status = self._team_switch_coordinator.get_status(
            operation_id,
            generation,
        )
        self._observe_team_switch_status(status)
        return self._serialize_switch_status(status)

    def _refresh_team_switch_policy(self) -> None:
        with self._operation_state_lock:
            accepted = tuple(self._accepted_v2_operations)
        for operation_id, generation in accepted:
            status = self._team_switch_coordinator.get_status(
                operation_id,
                generation,
            )
            self._observe_team_switch_status(status)

    def _observe_team_switch_status(
        self,
        status: OperationStatus,
    ) -> None:
        identity = (status.operation_id, status.generation)
        if (
            status.result in {"failed", "rejected"}
            and not status.profile_committed
        ):
            self._team_switch_policy.trip(status.reason)
            self._finish_v2_operation(identity)
        elif (
            status.result == "failed"
            and status.stage is SwitchStage.DEGRADED_IDLE
        ):
            self._team_switch_policy.trip(status.reason)
            self._finish_v2_operation(identity)
        elif status.result == "success":
            self._finish_v2_operation(identity)
        elif (
            status.result == "stale"
            and status.reason == "not_found"
        ):
            # Coordinator 的终态只保留有限时间；终态过期后查询会返回
            # stale/not_found。此时已无同 identity 的活动操作，壳层必须清理
            # 自己保留的 gate，否则客户端空闲超过保留期后会永久
            # operation_busy。无关 identity 由 _finish_v2_operation 的相等
            # 判断保护，不会误清当前操作。
            self._finish_v2_operation(identity)

    def _claim_v2_operation(self, operation_id: str) -> bool:
        """原子拒绝与旧顺序操作或另一 v2 操作并发。"""
        with self._operation_state_lock:
            if self._legacy_operation_depth or self._v2_operation_identity:
                return False
            self._v2_operation_identity = (operation_id, 0)
            return True

    def _release_v2_operation(self) -> None:
        with self._operation_state_lock:
            self._v2_operation_identity = None

    def _finish_v2_operation(self, identity: tuple[str, int]) -> None:
        with self._operation_state_lock:
            self._accepted_v2_operations.discard(identity)
            if self._v2_operation_identity == identity:
                self._v2_operation_identity = None
        with self._v2_timing_lock:
            self._v2_timing_starts.pop(identity, None)

    def _claim_legacy_operation(self) -> bool:
        """旧入口进入统一门禁；同一线程嵌套调用保持可重入。"""
        thread_id = threading.get_ident()
        with self._operation_state_lock:
            depth = self._legacy_operation_depth.get(thread_id, 0)
            if depth:
                self._legacy_operation_depth[thread_id] = depth + 1
                return True
            if self._v2_operation_identity is not None:
                return False
            self._legacy_operation_depth[thread_id] = 1
            return True

    def _release_legacy_operation(self) -> None:
        thread_id = threading.get_ident()
        with self._operation_state_lock:
            depth = self._legacy_operation_depth.get(thread_id, 0)
            if depth <= 1:
                self._legacy_operation_depth.pop(thread_id, None)
            else:
                self._legacy_operation_depth[thread_id] = depth - 1

    def get_switch_context(
        self,
        operation_id: str,
        generation: int,
    ) -> dict[str, Any]:
        """返回页面上报所需的公开绑定，不返回 handoff 或 secret。"""
        with self._team_switch_context_lock:
            context = self._team_switch_contexts.get(
                (operation_id, generation)
            )
            return dict(context or {})

    def report_switch_milestone(
        self,
        payload: dict[str, Any],
    ) -> dict[str, Any]:
        """校验固定 payload 后交给 Coordinator 原子消费。"""
        try:
            purpose = MilestonePurpose(payload["purpose"])
            report = MilestoneReport(
                operation_id=payload["operation_id"],
                generation=payload["generation"],
                slot_generation=payload["slot_generation"],
                purpose=purpose,
                session_id=payload["session_id"],
                milestone=payload["milestone"],
                proof=payload["proof"],
            )
        except (KeyError, TypeError, ValueError):
            status = OperationStatus(
                "",
                0,
                self._team_switch_coordinator.state,
                "rejected",
                "invalid_report",
                False,
            )
            return self._serialize_milestone_result(
                MilestoneResult(
                    False,
                    "rejected",
                    "invalid_report",
                    status,
                )
            )

        result = self._team_switch_coordinator.report_milestone(report)
        # interactive 是完整体验的性能终点，必须先写入耗时再释放状态，
        # 否则 _finish_v2_operation 会提前移除该操作的起始时间。
        self._record_switch_milestone(report, result)
        # interactive 由新页面上报；不能依赖已卸载旧页面的轮询来释放操作门禁。
        self._observe_team_switch_status(result.status)
        if result.status.profile_committed:
            with self._team_switch_context_lock:
                context = self._team_switch_contexts.get(
                    (report.operation_id, report.generation),
                    {},
                )
                profile_id = context.get("profile_id")
            if isinstance(profile_id, str) and profile_id:
                self._current_profile_id = profile_id
                self._invalidate_org_snapshots()
        return self._serialize_milestone_result(result)

    @staticmethod
    def _serialize_switch_status(
        status: OperationStatus,
    ) -> dict[str, Any]:
        return {
            "operation_id": status.operation_id,
            "generation": status.generation,
            "stage": status.stage.value,
            "result": status.result,
            "reason": status.reason,
            "profile_committed": status.profile_committed,
        }

    @classmethod
    def _serialize_milestone_result(
        cls,
        result: MilestoneResult,
    ) -> dict[str, Any]:
        return {
            "accepted": result.accepted,
            "result": result.result,
            "reason": result.reason,
            "status": cls._serialize_switch_status(result.status),
        }

    def _record_switch_milestone(
        self,
        report: MilestoneReport,
        result: MilestoneResult,
    ) -> None:
        stage = (
            report.milestone
            if report.milestone
            in {
                "navigation_committed",
                "shell_ready",
                "interactive",
            }
            else "unknown"
        )
        self._record_v2_timing(
            (report.operation_id, report.generation),
            stage=stage,
            result="success" if result.accepted else "failed",
        )

    def _record_v2_timing(
        self,
        identity: tuple[str, int],
        *,
        stage: str,
        result: str,
    ) -> None:
        """按 Shell 单调时钟记录 bridge 到真实页面里程碑的耗时。"""
        with self._v2_timing_lock:
            timing = self._v2_timing_starts.get(identity)
            if timing is None:
                return
            started_at, click_to_overlay_ms, click_to_bridge_ms = timing
            if stage == "interactive" or result == "failed":
                self._v2_timing_starts.pop(identity, None)
        elapsed_ms = max(0.0, (time.monotonic() - started_at) * 1000)
        self._team_switch_metrics.record(
            stage=stage,
            result=result,
            duration_ms=elapsed_ms,
            error_code=None if result == "success" else "unknown",
        )
        logger.info(
            "团队切换 v2 耗时: operation_id=%s generation=%d stage=%s "
            "bridge_to_stage_ms=%.1f click_to_overlay_ms=%.1f "
            "click_to_bridge_ms=%.1f result=%s",
            identity[0],
            identity[1],
            stage,
            elapsed_ms,
            max(0.0, click_to_overlay_ms),
            max(0.0, click_to_bridge_ms),
            result,
        )

    def _resolve_team_switch_target(
        self,
        target_id: str,
        operation_id: str,
        kind: str,
    ) -> ResolvedTarget:
        """只从 ProfileStore 或当前身份创建受操作持有的目标。"""
        if kind == "join":
            profile_id, provisional = self._provision_profile_for_org(
                target_id,
                operation_id,
            )
        else:
            profile_id = target_id
            provisional = None
        profile = self._profile_store.get_profile(profile_id)
        if profile is None:
            raise ProfileNotFoundError(profile_id)
        lifecycle = profile.get("lifecycle_state", "ready")
        owner = profile.get("provisioning_operation_id")
        if lifecycle != "ready" and owner != operation_id:
            raise RuntimeError("profile_operation_conflict")
        namespace = self._profile_store.ensure_profile_namespace(profile_id)
        profile = dict(profile)
        profile["profile_id"] = profile_id
        profile["profile_namespace"] = namespace
        working_dir = Path(profile["working_dir"]).expanduser().resolve()
        profile["working_dir"] = str(working_dir)
        return ResolvedTarget(
            profile=profile,
            profile_id=profile_id,
            working_dir=working_dir,
            profile_namespace=namespace,
            provisional_operation_id=provisional,
        )

    def _provision_profile_for_org(
        self,
        target_id: str,
        operation_id: str,
    ) -> tuple[str, str | None]:
        active = self._profile_store.get_active_profile()
        if active is None:
            raise RuntimeError("missing_active_profile")
        user_id = str(active.get("user_id", ""))
        org_id = target_id
        if "/" in target_id:
            target_user, org_id = target_id.split("/", 1)
            if target_user != user_id:
                raise ProfileIdentityMismatchError()
        profile_id = ProfileStore.make_profile_id(user_id, org_id)
        existing = self._profile_store.get_profile(profile_id)
        if existing is not None and existing.get(
            "lifecycle_state", "ready"
        ) == "ready":
            return profile_id, None

        source_dir = Path(active["working_dir"])
        auth_file = source_dir / ".secret" / "auth.json"
        try:
            auth_data = json.loads(auth_file.read_text(encoding="utf-8"))
            access_token = _decrypt_sso_access_token(
                auth_data, auth_file.parent
            )
            user_info = auth_data.get("sso_user_info") or {}
        except Exception as exc:
            raise RuntimeError("login_credential_unavailable") from exc
        self._require_profile_identity(user_info, user_id)
        if not access_token:
            raise RuntimeError("login_credential_unavailable")
        ed_api_url = self._pending_ed_api_url or self.get_ed_api_url()
        orgs = self._get_or_fetch_orgs(
            access_token,
            ed_api_url,
            user_id,
        )
        org_info = next(
            (org for org in orgs if str(org.get("id", "")) == org_id),
            None,
        )
        if org_info is None:
            raise RuntimeError("org_not_available")
        self._restore_recovered_provisional(
            profile_id,
            _profile_dir(self._app_root, user_id, org_id),
        )
        created = create_profile(
            self._profile_store,
            self._app_root,
            user_info,
            org_info,
            sso_token_data=None,
            source_profile_dir=source_dir,
            operation_id=operation_id,
            activate=False,
        )
        return created, operation_id

    def _navigate_team_switch_candidate(
        self,
        slot: BackendSlot,
        status: OperationStatus,
    ) -> PreparedNavigation:
        self._record_v2_timing(
            (status.operation_id, status.generation),
            stage="backend_ready",
            result="success",
        )
        return self._prepare_slot_navigation(
            slot,
            status,
            MilestonePurpose.CANDIDATE,
        )

    def _prepare_slot_navigation(
        self,
        slot: BackendSlot,
        status: OperationStatus,
        purpose: MilestonePurpose,
    ) -> PreparedNavigation:
        """先注册 digest，Coordinator 绑定 session 后才真正写页面。"""
        if self._team_switch_navigator is None:
            raise RuntimeError("navigator_unavailable")
        session_id, url = self._register_slot_handoff(
            slot,
            operation_id=status.operation_id,
            generation=status.generation,
            purpose=purpose.value,
        )
        context = {
            "operation_id": status.operation_id,
            "generation": status.generation,
            "slot_generation": slot.identity.generation,
            "purpose": purpose.value,
            "session_id": session_id,
            "profile_namespace": slot.identity.profile_namespace,
            "profile_id": slot.identity.profile_id,
        }
        with self._team_switch_context_lock:
            self._team_switch_contexts[
                (status.operation_id, status.generation)
            ] = context
        def commit_navigation() -> None:
            navigator = self._team_switch_navigator
            if navigator is None:
                raise RuntimeError("navigator_unavailable")
            navigator(url)

        return PreparedNavigation(session_id, commit_navigation)

    def _register_slot_handoff(
        self,
        slot: BackendSlot,
        *,
        operation_id: str,
        generation: int,
        purpose: str,
        attempts: int = 1,
    ) -> tuple[str, str]:
        """注册一次性 handoff 并返回 fragment handoff URL。

        第一轮用同一 payload 幂等重试（对网络层失败友好）；若全部失败，
        再用全新 payload（重新取 now、重新生成 code/session）补试一轮——
        开机初期 NTP 校时会让固定 expires_at 的重试整轮失效。
        """
        last_error: Exception | None = None
        for round_index in range(2):
            raw_code = secrets.token_urlsafe(32)
            session_id = secrets.token_hex(16)
            payload = {
                "session_id": session_id,
                "operation_id": operation_id,
                "generation": generation,
                "slot_generation": slot.identity.generation,
                "purpose": purpose,
                "digest": hashlib.sha256(raw_code.encode()).hexdigest(),
                "expires_at": time.time() + _DESKTOP_HANDOFF_TTL_SECONDS,
            }
            for attempt in range(max(1, attempts)):
                try:
                    self._post_slot_json(
                        slot,
                        "/api/sso/desktop-handoff/register",
                        payload,
                        expected_status=204,
                    )
                    encoded = urllib.parse.quote(raw_code, safe="")
                    url = self._console_url_for_slot(slot, encoded)
                    return session_id, url
                except Exception as exc:
                    last_error = exc
                if attempt + 1 < max(1, attempts):
                    time.sleep(_DESKTOP_SESSION_RETRY_DELAY)
            time.sleep(_DESKTOP_SESSION_RETRY_DELAY)
        assert last_error is not None
        raise last_error

    def _console_url_for_slot(
        self,
        slot: BackendSlot,
        encoded_handoff_code: str,
    ) -> str:
        """构造页面 URL；静态壳与后端 API 的 origin 必须显式分离。"""
        backend_origin = f"http://{self._host}:{slot.port}"
        static_origin = (
            self._console_static_server.origin
            if self._console_static_server is not None
            else ""
        )
        if not static_origin:
            return f"{backend_origin}/login#desktop_handoff={encoded_handoff_code}"
        query = urllib.parse.urlencode({"api_origin": backend_origin})
        return (
            f"{static_origin}/login?{query}"
            f"#desktop_handoff={encoded_handoff_code}"
        )

    @staticmethod
    def _slot_for_report(
        coordinator: TeamSwitchCoordinator,
        purpose: MilestonePurpose,
    ) -> BackendSlot | None:
        if purpose is MilestonePurpose.ROLLBACK_ACTIVE:
            return coordinator.rollback_slot
        return coordinator.candidate_slot

    def _verify_team_switch_proof(self, report: MilestoneReport) -> bool:
        slot = self._slot_for_report(
            self._team_switch_coordinator,
            report.purpose,
        )
        if slot is None:
            return False
        claims = decode_milestone_proof(
            report.proof,
            handshake_secret=slot.handshake_secret,
        )
        valid = bool(
            claims is not None
            and claims.operation_id == report.operation_id
            and claims.generation == report.generation
            and claims.slot_generation == report.slot_generation
            and claims.purpose == report.purpose.value
            and claims.session_id == report.session_id
            and claims.milestone == report.milestone
            and claims.audience == slot.desktop_audience
            and claims.profile_namespace
            == slot.identity.profile_namespace
        )
        if not valid or claims is None:
            return False
        now = int(time.time())
        with self._milestone_proof_lock:
            self._consumed_milestone_proofs = {
                nonce: expires_at
                for nonce, expires_at in self._consumed_milestone_proofs.items()
                if expires_at >= now
            }
            if claims.nonce in self._consumed_milestone_proofs:
                return False
            if (
                len(self._consumed_milestone_proofs)
                >= _MAX_CONSUMED_MILESTONE_PROOFS
            ):
                return False
            self._consumed_milestone_proofs[claims.nonce] = claims.expires_at
        return True

    def _recover_team_switch(
        self,
        action: str,
        status: OperationStatus,
        lease: SideEffectLease | None = None,
    ) -> BackendSlot | PreparedNavigation | None:
        if action == "rollback_active":
            if lease is None:
                raise RuntimeError("rollback_lease_required")
            slot = self._team_switch_coordinator.rollback_slot
            if slot is None:
                raise RuntimeError("rollback_slot_missing")
            return self._prepare_slot_navigation(
                slot,
                status,
                MilestonePurpose.ROLLBACK_ACTIVE,
            )
        if action == "reload_console":
            slot = self._team_switch_coordinator.candidate_slot
            if slot is None:
                return None
            return self._prepare_slot_navigation(
                slot,
                status,
                MilestonePurpose.CANDIDATE,
            )
        if action != "restart_backend":
            return None
        profile_id = self._profile_store.get_active_profile_id()
        if not profile_id:
            return None
        budget = self._team_switch_coordinator.recovery_budget(
            status.operation_id,
            status.generation,
        )
        if (
            budget is None
            or budget.cancellation.is_set()
            or budget.deadline.remaining() <= 0
        ):
            raise RuntimeError("recovery_cancelled")
        existing = self._backend_runtime.active_slot
        if existing is not None:
            self._backend_runtime.stop_slot(
                existing,
                timeout=min(5.0, budget.deadline.remaining()),
            )
            if not self._backend_runtime.wait_slot_stopped(
                existing,
                timeout=budget.deadline.remaining(),
            ):
                raise RuntimeError("recovery_old_slot_not_stopped")
        if (
            budget.cancellation.is_set()
            or budget.deadline.remaining() <= 0
        ):
            raise RuntimeError("recovery_cancelled")
        resolved = self._resolve_team_switch_target(
            profile_id,
            status.operation_id,
            "recover_active",
        )
        if (
            budget.cancellation.is_set()
            or budget.deadline.remaining() <= 0
        ):
            raise RuntimeError("recovery_cancelled")
        return self._backend_runtime.start_slot(
            resolved.profile,
            operation_id=status.operation_id,
            generation=status.generation,
            mode=SlotMode.ACTIVE,
            deadline=budget.deadline,
            cancellation=budget.cancellation,
            initial_handoff_purpose="candidate",
        )

    def _post_slot_json(
        self,
        slot: BackendSlot,
        path: str,
        payload: dict[str, Any] | None,
        *,
        expected_status: int,
        timeout: float = _DESKTOP_SESSION_TIMEOUT,
    ) -> dict[str, Any]:
        body = None
        headers = {
            "X-EazyBot-Desktop-Handshake": slot.handshake_secret,
        }
        if payload is not None:
            body = json.dumps(payload, separators=(",", ":")).encode()
            headers["Content-Type"] = "application/json"
        request = urllib.request.Request(
            f"http://{self._host}:{slot.port}{path}",
            data=body,
            method="POST",
            headers=headers,
        )
        with urllib.request.urlopen(
            request,
            timeout=timeout,
        ) as response:
            if response.status != expected_status:
                raise RuntimeError("desktop_slot_request_failed")
            raw = response.read()
        if not raw:
            return {}
        decoded = json.loads(raw.decode("utf-8"))
        if not isinstance(decoded, dict):
            raise RuntimeError("desktop_slot_response_invalid")
        return decoded

    def _activate_promoted_candidate(
        self,
        operation_id: str,
        generation: int,
    ) -> bool:
        slot = self._backend_runtime.active_slot
        if (
            slot is None
            or slot.identity.operation_id != operation_id
            or slot.identity.generation != generation
        ):
            return False
        try:
            result = self._post_slot_json(
                slot,
                "/api/desktop/activate",
                None,
                expected_status=200,
                timeout=_DESKTOP_ACTIVATE_TIMEOUT,
            )
        except Exception as exc:
            logger.error(
                "候选后端激活失败: reason=%s",
                safe_exception_reason(exc),
            )
            return False
        activated = result.get("activated") is True
        if activated:
            self._write_runtime_registry()
            try:
                from ..config.utils import write_last_api

                write_last_api("127.0.0.1", slot.port)
            except Exception:
                logger.warning(
                    "回写 last_api 失败（团队切换），不影响激活",
                    exc_info=True,
                )
        return activated

    def _ensure_lease_heartbeat(self, profile_namespace: str) -> None:
        """在 Popen 前启动 ≤1 秒的 Shell lease 心跳。"""
        with self._lease_heartbeat_lock:
            self._lease_heartbeat_namespace = profile_namespace
            self._write_runtime_registry(profile_namespace)
            thread = self._lease_heartbeat_thread
            if thread is not None and thread.is_alive():
                return
            self._lease_heartbeat_stop.clear()

            def _heartbeat() -> None:
                while not self._lease_heartbeat_stop.wait(0.75):
                    try:
                        self._write_runtime_registry()
                    except OSError as exc:
                        logger.warning(
                            "runtime registry 心跳写入失败: reason=%s",
                            safe_exception_reason(exc),
                        )

            self._lease_heartbeat_thread = threading.Thread(
                target=_heartbeat,
                name="eazybot-shell-lease",
                daemon=True,
            )
            self._lease_heartbeat_thread.start()

    def _write_runtime_registry(
        self,
        fallback_namespace: str = "",
    ) -> None:
        slot = self._backend_runtime.active_slot
        process_pid: int | None = None
        active_port: int | None = None
        namespace = fallback_namespace or self._lease_heartbeat_namespace
        if slot is not None and slot.process.poll() is None:
            candidate_pid = getattr(slot.process, "pid", None)
            if (
                isinstance(candidate_pid, int)
                and not isinstance(candidate_pid, bool)
                and candidate_pid > 0
            ):
                process_pid = candidate_pid
                active_port = slot.port
            namespace = slot.identity.profile_namespace
        if not namespace:
            self._runtime_registry.remove()
            return
        self._lease_heartbeat_namespace = namespace
        self._runtime_registry.write(
            DesktopRuntimeRecord(
                shell_pid=os.getpid(),
                shell_started_at=self._shell_started_at,
                active_backend_pid=process_pid,
                active_port=active_port,
                profile_namespace=namespace,
                lease_id=self._lease_id,
            )
        )

    def mint_console_url(self) -> str:
        """为初始 active 注册一次性 v2 handoff 并返回 fragment URL。"""
        slot = self._backend_runtime.active_slot
        if slot is None:
            return ""
        if slot.initial_handoff_purpose != "initial_active":
            return ""
        try:
            _session_id, url = self._register_slot_handoff(
                slot,
                operation_id=slot.identity.operation_id,
                generation=slot.identity.generation,
                purpose="initial_active",
                attempts=_DESKTOP_SESSION_ATTEMPTS,
            )
            return url
        except Exception as exc:
            last_error = exc

        reason = (
            safe_exception_reason(last_error)
        )
        logger.warning(
            "桌面会话握手失败（已尝试 %d 次），"
            "停止 Console 导航: reason=%s",
            _DESKTOP_SESSION_ATTEMPTS,
            reason,
        )
        return ""

    def fail_console_handoff(self) -> None:
        """会话交接失败时停止后端，并进入可重试的壳层错误态。"""
        self.stop_backend()
        self._login_seq += 1
        self._login_state = "failed"
        self._login_error = "客户端登录态建立失败，请重新登录"

    @property
    def connection_state(self) -> str:
        """ED 连接探测三态：online / degraded / offline。

        壳每 5 分钟探 ED ``/health`` + 检查 SSO token 过期时间戳。
        来源：``后端TODO/09`` §9.6。
        """
        with self._connection_lock:
            return self._connection_state

    @property
    def app_root(self) -> Path:
        return self._app_root

    def load_global_env(self) -> dict[str, str]:
        """加载全局 .env，返回 env dict。"""
        return load_env_chain(self._app_root)

    def get_ed_sso_url(self) -> str:
        """返回 ED SSO URL（从 env 或全局 .env）。"""
        url = os.environ.get(
            "EAZYDEVELOP_SSO_URL", ""
        ).strip()
        if not url:
            env = self.load_global_env()
            url = env.get("EAZYDEVELOP_SSO_URL", "")
        return url.rstrip("/")

    def get_ed_api_url(self) -> str:
        """返回 ED API URL（默认与 SSO URL 同源）。"""
        url = os.environ.get(
            "EAZYDEVELOP_API_BASE_URL", ""
        ).strip()
        if not url:
            env = self.load_global_env()
            url = env.get("EAZYDEVELOP_API_BASE_URL", "")
        if not url:
            url = self.get_ed_sso_url()
        return url.rstrip("/")

    def _prepare_org_cache_key(
        self, ed_api_url: str, user_id: str
    ) -> OrgCacheKey:
        """建立当前缓存上下文，并清掉已经切离的旧租户 key。"""
        key = OrgSnapshotCache.make_key(ed_api_url, user_id)
        with self._org_cache_context_lock:
            previous = self._org_cache_context_key
            if previous is not None and previous != key:
                self._org_snapshot_cache.invalidate(previous)
            self._org_cache_context_key = key
        return key

    def _invalidate_org_snapshots(
        self, key: OrgCacheKey | None = None
    ) -> None:
        """失效团队快照；不保留跨登录身份的缓存上下文。"""
        self._org_snapshot_cache.invalidate(key)
        with self._org_cache_context_lock:
            if key is None or self._org_cache_context_key == key:
                self._org_cache_context_key = None

    def _require_profile_identity(
        self, user_info: object, expected_user_id: str
    ) -> None:
        """确认凭据用户属于目标 Profile，否则清缓存并安全拒绝。"""
        actual_user_id = ""
        if isinstance(user_info, dict):
            value = user_info.get("user_id")
            if isinstance(value, str):
                actual_user_id = value
        if (
            not expected_user_id
            or not actual_user_id
            or actual_user_id != expected_user_id
        ):
            self._invalidate_org_snapshots()
            raise ProfileIdentityMismatchError()

    def _get_or_fetch_orgs(
        self,
        access_token: str,
        ed_api_url: str,
        user_id: str,
    ) -> list[dict]:
        """读取共享快照；ED 鉴权拒绝时立即使当前 key 失效。"""
        key = self._prepare_org_cache_key(ed_api_url, user_id)
        try:
            return self._org_snapshot_cache.get_or_fetch(
                key,
                lambda: fetch_org_list(access_token, ed_api_url),
            )
        except BaseException as exc:
            if _is_auth_http_error(exc):
                self._invalidate_org_snapshots(key)
            raise

    def get_valid_active_profile(self) -> Optional[dict]:
        """返回有效 active profile，无则 None。

        ``profiles.json`` 中的 refresh 到期时间是客户端创建 profile 时
        生成的本地估算值：``switch_profile()`` / 团队切换 v2 只调
        ``activate_profile()``，并不回写该时间戳；token 轮换
        （``_sync_sso_tokens_to_siblings``）也只落 ``auth.json``，不写
        ``profiles.json``。因此它既不会随登录续期，也不会随退出登录
        以外的场景归零，不能单独据此断言 ED 登录已失效。

        真源改为 ``auth.json`` 的 ``sso_refresh_token`` **内容**（而非
        文件是否存在——``_clear_sso_tokens()`` 退出登录时只 pop 掉
        几个 key，文件本身仍在）：非空即仍登录，忽略本地估算时间戳；
        为空/缺失即明确的登出痕迹。只有 auth.json 不存在或读取失败
        （旧 profile / 损坏 / 权限问题）时，才回退到历史时间戳判定，
        且该判定链路不得把异常抛穿到探测线程。

        Fix E（对应 Codex 二审 C1）：登出墓碑判断排在
        **最前**、先于 ``sso_refresh_token`` 判断——退出登录后、
        `stop_backend()` 之前，后端仍可能迟到写回 token，若只看
        refresh_token 是否非空会被这次竞态误判为仍登录。

        Fix F（对应 Codex 二审 C2）：``auth_data`` 若不是 dict（如
        ``[]`` / ``"str"`` / ``123``），一律按凭据损坏 fail closed
        返回 None，**不回落**到时间戳判定——回落等于把一份损坏的
        凭据文件当「文件不在」处理，反而可能把真损坏的凭据救活。
        """
        profile = self._profile_store.get_active_profile()
        if profile is None:
            return None

        # 路径解析走 validated_profile_auth_file()：它校验 working_dir
        # 仍在 app_root 内、且 auth.json 未被软链跳转，挡住越界与软链
        # 逃逸；空 working_dir 同样不会被 Path("") 解析到进程 cwd。
        auth_file = validated_profile_auth_file(
            self._app_root, profile
        )
        if auth_file is None:
            # 空 working_dir 不得被 Path("") 解析成 "."，否则会拿
            # ./.secret/auth.json 去探测进程 cwd 并据此判定登录态（R5）。
            legacy_working_dir = profile.get("working_dir", "")
            legacy_auth = (
                Path(legacy_working_dir).expanduser()
                / ".secret"
                / "auth.json"
            ) if legacy_working_dir else None
            if legacy_auth is not None and legacy_auth.is_file():
                logger.warning("active profile 工作目录无效")
                return None

        if auth_file is not None and auth_file.is_file():
            # 哨兵：区分「读取/解析抛异常」与「内容就是合法 JSON
            # null」——两者都会让 ``auth_data is None``，但前者须回落
            # 到时间戳判定（R3/R4），后者是 Fix F 要 fail closed 的
            # 非 dict 根节点之一（R25），不能混用同一个 None 值判断。
            _read_failed = object()
            try:
                auth_data = json.loads(
                    auth_file.read_text(encoding="utf-8")
                )
            except (OSError, ValueError):
                # 必须捕 ValueError 而非仅 json.JSONDecodeError：
                # auth.json 若含非法 UTF-8，read_text() 抛的是
                # UnicodeDecodeError，它同为 ValueError 子类但**不是**
                # JSONDecodeError，只捕后者会漏网并把异常抛进探测线程。
                auth_data = _read_failed
            if auth_data is not _read_failed:
                if not isinstance(auth_data, dict):
                    # Fix F：非 dict 根节点视为凭据损坏，fail closed，
                    # 不得回落到时间戳判定（R25）。
                    logger.warning(
                        "active profile 的 auth.json 根节点不是 "
                        "dict，判定为凭据损坏，fail closed"
                    )
                    return None
                if auth_data.get(SSO_LOGOUT_TOMBSTONE_FIELD):
                    # Fix E：墓碑判断最高优先级，先于 refresh_token
                    # 判断——挡住「退出登录后后端迟到写回 token」竞态
                    # （R22/R23）。
                    logger.info(
                        "active profile 带退出登录墓碑标记，"
                        "判定为已退出登录"
                    )
                    return None
                if auth_data.get("sso_refresh_token"):
                    return profile
                logger.info(
                    "active profile 的 auth.json 无 refresh token，"
                    "判定为已退出登录"
                )
                return None
            # auth.json 存在但读取失败，不据此误判登出，
            # 回退到下方的历史时间戳判定。
            logger.warning(
                "active profile 的 auth.json 读取失败，回退时间戳判定"
            )

        sso = profile.get("sso", {})
        refresh_expires = sso.get(
            "refresh_token_expires_at", 0
        )
        if not refresh_expires:
            logger.info(
                "active profile 已标记为退出登录"
            )
            return None

        if time.time() > refresh_expires:
            logger.info(
                "旧 active profile 无有效 refresh_token 时间戳"
            )
            return None

        return profile

    def login_and_create_profile(
        self,
        ed_sso_url: str,
        ed_api_url: str,
        org_info: Optional[dict] = None,
    ) -> Optional[str]:
        """SSO 登录 -> 换 token -> （选团队）-> 创建 profile。

        Args:
            ed_sso_url: ED SSO provider URL。
            ed_api_url: ED API base URL。
            org_info: 指定团队（单团队自动选中或 UI 选择后传入）。
                None 表示需要拉团队列表；单团队自动选中，多团队
                返回 None 让 UI 层处理。

        Returns:
            profile_id 或 None（失败/需要 UI 选团队）。
        """
        self._invalidate_org_snapshots()
        ott = start_sso_login(ed_sso_url)
        if not ott:
            logger.warning("SSO 登录未获取到 token")
            return None

        token_data = exchange_sso_token(ott)
        if "error" in token_data:
            logger.error("SSO token 交换失败: reason=remote_rejected")
            return None

        access_token = token_data.get("access_token", "")
        user_info = token_data.get("user") or {}

        if org_info is None:
            try:
                orgs = self._get_or_fetch_orgs(
                    access_token,
                    ed_api_url,
                    str(user_info.get("user_id", "")),
                )
            except Exception as exc:
                logger.error(
                    "获取团队列表失败: reason=%s",
                    safe_exception_reason(exc),
                )
                return None
            if not orgs:
                logger.warning("用户不属于任何团队")
                return None
            if len(orgs) == 1:
                org_info = orgs[0]
            else:
                logger.info("多团队，需要 UI 选择")
                return None

        pid = create_profile(
            self._profile_store,
            self._app_root,
            user_info,
            org_info,
            token_data,
        )
        self._current_profile_id = pid
        self._invalidate_org_snapshots()
        return pid

    def do_sso_login(
        self, ed_sso_url: str, ed_api_url: str
    ) -> bool:
        """12.2：SSO 登录 + 拉团队列表，设置 _login_state。

        单团队：自动创建 profile，caller 后续 start_backend + load_url。
        多团队：存中间状态到 _pending_*，_login_state='multi_org'，
                caller 加载团队选择页，bridge select_org 待用户选择。
        失败：_login_state='failed'，_login_error 填原因。

        返回 True 表示登录成功（无论单/多团队），False 失败/取消。
        """
        self._login_seq += 1
        self._login_state = "logging_in"
        self._login_error = ""
        self._pending_ed_sso_url = ed_sso_url
        self._pending_ed_api_url = ed_api_url
        self._invalidate_org_snapshots()

        ott = start_sso_login(ed_sso_url)
        if not ott:
            self._login_state = "failed"
            # 覆盖「真超时」与「已在其他页面完成登录」两种真实处境，
            # 面向用户、不带品牌名（stree 裁定）。
            self._login_error = (
                "本次登录未完成，如已在其他页面完成登录可忽略，"
                "否则请重新登录"
            )
            return False

        t0 = time.perf_counter()
        token_data = exchange_sso_token(ott)
        t1 = time.perf_counter()
        logger.info(
            "SSO token 交换完成，耗时 %.2fs",
            t1 - t0,
        )
        if "error" in token_data:
            self._login_state = "failed"
            self._login_error = (
                f"token 交换失败: {_map_sso_error(token_data['error'])}"
            )
            return False

        access_token = token_data.get("access_token", "")
        user_info = token_data.get("user") or {}

        try:
            orgs = self._get_or_fetch_orgs(
                access_token,
                ed_api_url,
                str(user_info.get("user_id", "")),
            )
            t2 = time.perf_counter()
            logger.info(
                "团队列表拉取完成，耗时 %.2fs（共 %d 个团队）",
                t2 - t1,
                len(orgs),
            )
        except Exception as exc:
            self._login_state = "failed"
            self._login_error = f"获取团队列表失败: {exc}"
            return False

        if not orgs:
            self._login_state = "failed"
            self._login_error = "用户不属于任何团队"
            return False

        if len(orgs) == 1:
            pid = create_profile(
                self._profile_store,
                self._app_root,
                user_info,
                orgs[0],
                token_data,
            )
            self._current_profile_id = pid
            self._login_state = "success"
            self._invalidate_org_snapshots()
            return True

        self._pending_orgs = orgs
        self._pending_token_data = token_data
        self._pending_user_info = user_info
        self._login_state = "multi_org"
        return True

    def create_profile_with_org(
        self, org_id: str
    ) -> Optional[str]:
        """12.2：多团队用户选定后，用 pending 状态创建 profile。"""
        if not self._pending_token_data or not self._pending_user_info:
            return None
        org_info = None
        for org in self._pending_orgs:
            if org.get("id") == org_id:
                org_info = org
                break
        if org_info is None:
            logger.warning(
                "团队选择项未匹配（候选团队数=%d）",
                len(self._pending_orgs),
            )
            return None
        pid = create_profile(
            self._profile_store,
            self._app_root,
            self._pending_user_info,
            org_info,
            self._pending_token_data,
        )
        self._current_profile_id = pid
        self._login_state = "success"
        self._pending_orgs = []
        self._pending_token_data = None
        self._pending_user_info = None
        self._invalidate_org_snapshots()
        return pid

    def list_available_orgs(self) -> dict:
        """返回 ED 全量团队，逐条标注 installed（本机是否已有 profile）。

        用当前 active profile 的 access_token 调 ED /api/org/list。
        返回 ``{"orgs": [...], "error": "..."}``：
        - 成功时 error 为空，orgs 为团队列表（每条含 id/org_name/
          avatar/org_type/installed）。
        - 失败时 orgs 为空，error 填原因，前端据此提示「请重新登录」等。
        installed 仅对**当前 user_id** 下的 profile 标注，避免换过账号
        的机器误判。
        """
        with team_switch_stage("resolve_active_profile") as stage:
            profile = self.get_valid_active_profile()
            if not profile:
                stage.fail("missing_active_profile")
                return {
                    "orgs": [],
                    "error": "无有效登录态，请重新登录",
                }

        auth_file = (
            Path(profile["working_dir"])
            / ".secret"
            / "auth.json"
        )
        current_user_id = str(profile.get("user_id", ""))
        with team_switch_stage("read_login_credential") as stage:
            try:
                auth_data = json.loads(
                    auth_file.read_text(encoding="utf-8")
                )
                access_token = _decrypt_sso_access_token(
                    auth_data, auth_file.parent
                )
            except Exception:
                stage.fail("read_failed")
                return {
                    "orgs": [],
                    "error": "登录凭据读取失败，请重新登录",
                }

            if not access_token:
                stage.fail("missing_access_token")
                return {
                    "orgs": [],
                    "error": "登录态已失效，请重新登录",
                }
            try:
                self._require_profile_identity(
                    auth_data.get("sso_user_info"),
                    current_user_id,
                )
            except ProfileIdentityMismatchError as exc:
                stage.fail("identity_mismatch")
                return {"orgs": [], "error": str(exc)}

        ed_api_url = self._pending_ed_api_url
        if not ed_api_url:
            ed_api_url = self.get_ed_api_url()

        try:
            with team_switch_stage("fetch_org_list"):
                orgs = self._get_or_fetch_orgs(
                    access_token,
                    ed_api_url,
                    current_user_id,
                )
        except Exception as exc:
            logger.warning(
                "获取 ED 全量团队失败: reason=%s",
                safe_exception_reason(exc),
            )
            return {
                "orgs": [],
                "error": f"获取团队列表失败: {exc}",
            }

        with team_switch_stage("map_installed_orgs"):
            installed_ids = {
                p["org_id"]
                for p in self._profile_store.list_profiles()
                if p.get("user_id") == current_user_id
            }

            result = []
            for org in orgs:
                org_id = org.get("id", "")
                result.append(
                    {
                        "id": org_id,
                        "org_name": org.get("org_name", ""),
                        "avatar": org.get("avatar", ""),
                        "org_type": org.get("org_type", ""),
                        "installed": org_id in installed_ids,
                    }
                )
        return {"orgs": result, "error": ""}

    def create_and_switch_org(self, org_id: str) -> None:
        """为未登录过的团队创建 profile 并切换。

        若该团队已有本地 profile，走现有 switch_profile；
        否则用 source_profile_dir 从当前 profile 复制 SSO token
        创建新 profile -> 起后端。复用 _switch_state 状态机。
        """
        if not self._team_switch_enabled:
            raise RuntimeError("团队切换功能未启用")
        if not self._switch_lock.acquire(blocking=False):
            self._switch_state = "busy"
            self._switch_error = "操作进行中，请等待"
            self._switch_seq += 1
            raise RuntimeError("操作进行中，请等待")
        if not self._claim_legacy_operation():
            self._switch_lock.release()
            self._switch_state = "busy"
            self._switch_error = "操作进行中，请等待"
            self._switch_seq += 1
            raise RuntimeError("操作进行中，请等待")
        provisional_pid: str | None = None
        provisioning_operation_id: str | None = None
        old_pid = self._current_profile_id
        logout_epoch = self._logout_epoch
        rollback_required = False
        try:
            self._switch_seq += 1
            self._switch_state = "switching"
            self._switch_error = ""

            profile = self._profile_store.get_profile(old_pid)
            if not profile:
                self._switch_state = "failed"
                self._switch_error = "无当前 profile"
                raise RuntimeError("无当前 profile")

            # installed 仅看当前 user_id 下的 profile，避免换过账号误判
            current_user_id = profile.get("user_id", "")
            source_profile_dir = Path(profile["working_dir"])
            installed_ids = {
                p["org_id"]
                for p in self._profile_store.list_profiles()
                if p.get("user_id") == current_user_id
            }
            if org_id in installed_ids:
                # org_id -> profile_id（<user_id>/<org_id>），不能传裸 org_id
                target_pid = ProfileStore.make_profile_id(
                    current_user_id, org_id
                )
                with team_switch_stage("switch_profile"):
                    self.switch_profile(target_pid)
                return

            ed_api_url = (
                self._pending_ed_api_url
                or self.get_ed_api_url()
            )
            auth_file = (
                source_profile_dir / ".secret" / "auth.json"
            )
            try:
                auth_data = json.loads(
                    auth_file.read_text(encoding="utf-8")
                )
                access_token = _decrypt_sso_access_token(
                    auth_data, auth_file.parent
                )
                user_info = (
                    auth_data.get("sso_user_info") or {}
                )
            except Exception:
                access_token = ""
                user_info = {}

            if not access_token:
                self._switch_state = "failed"
                self._switch_error = "无法获取 access_token"
                raise RuntimeError("无法获取 access_token")

            try:
                self._require_profile_identity(
                    user_info, str(current_user_id)
                )
            except ProfileIdentityMismatchError as exc:
                self._switch_state = "failed"
                self._switch_error = str(exc)
                raise

            try:
                with team_switch_stage("fetch_org_list"):
                    orgs = self._get_or_fetch_orgs(
                        access_token,
                        ed_api_url,
                        current_user_id,
                    )
            except Exception as exc:
                self._switch_state = "failed"
                self._switch_error = f"获取团队列表失败: {exc}"
                raise

            org_info = None
            for org in orgs:
                if org.get("id") == org_id:
                    org_info = org
                    break

            if not org_info:
                self._switch_state = "failed"
                self._switch_error = (
                    f"团队 {org_id} 不在您的团队列表中"
                )
                raise RuntimeError(
                    f"团队 {org_id} 不在您的团队列表中"
                )

            if not user_info.get("user_id"):
                self._switch_state = "failed"
                self._switch_error = "无法获取用户信息"
                raise RuntimeError("无法获取用户信息")

            rollback_required = True
            with team_switch_stage("stop_backend"):
                self.stop_backend()

            provisioning_operation_id = (
                f"legacy-switch-{secrets.token_hex(16)}"
            )
            provisional_pid = ProfileStore.make_profile_id(
                str(user_info["user_id"]), str(org_info["id"])
            )
            with team_switch_stage("create_profile"):
                pid = create_profile(
                    self._profile_store,
                    self._app_root,
                    user_info,
                    org_info,
                    sso_token_data=None,
                    source_profile_dir=source_profile_dir,
                    operation_id=provisioning_operation_id,
                    activate=False,
                )
                provisional_pid = pid
            self._current_profile_id = pid

            self.start_backend(pid)

            if self._logout_epoch != logout_epoch:
                self.stop_backend()
                self._current_profile_id = None
                rollback_required = False
                raise RuntimeError("已退出登录")

            with team_switch_stage("persist_active_profile"):
                self._profile_store.activate_profile(
                    pid,
                    operation_id=provisioning_operation_id,
                )
                provisional_pid = None
            rollback_required = False
            self._invalidate_org_snapshots()
            self._switch_state = "success"
        except Exception as exc:
            if isinstance(exc, OrgSnapshotInvalidated):
                self._switch_state = "failed"
                raise
            if self._logout_epoch != logout_epoch:
                rollback_required = False
                self._current_profile_id = None
                self._switch_state = "failed"
                raise RuntimeError("已退出登录") from None
            if rollback_required:
                self._rollback_profile_switch(
                    old_pid,
                    provisional_profile_id=provisional_pid,
                    provisioning_operation_id=(
                        provisioning_operation_id
                    ),
                )
            if self._switch_state not in (
                "failed",
                "busy",
            ):
                self._switch_state = "failed"
                self._switch_error = str(exc)
            raise
        finally:
            self._release_legacy_operation()
            self._switch_lock.release()

    def _rollback_profile_switch(
        self,
        old_profile_id: str | None,
        *,
        provisional_profile_id: str | None = None,
        provisioning_operation_id: str | None = None,
    ) -> None:
        """尽力恢复旧 Profile，所有二次异常只记录不再抛出。"""
        try:
            self.stop_backend()
        except Exception as exc:
            logger.error(
                "停止候选后端失败: reason=%s",
                safe_exception_reason(exc),
            )

        self._current_profile_id = old_profile_id
        if old_profile_id:
            try:
                self._profile_store.activate_profile(old_profile_id)
            except Exception as exc:
                logger.error(
                    "恢复旧 active Profile 失败: reason=%s",
                    safe_exception_reason(exc),
                )
            try:
                with team_switch_stage("rollback_backend"):
                    self.restart_backend()
            except Exception as exc:
                logger.error(
                    "回滚到旧 Profile 后端失败: reason=%s",
                    safe_exception_reason(exc),
                )

        if provisional_profile_id and provisioning_operation_id:
            try:
                self._profile_store.discard_provisional(
                    provisional_profile_id,
                    provisioning_operation_id,
                )
            except Exception as exc:
                logger.error(
                    "清理候选 Profile 索引失败: reason=%s",
                    safe_exception_reason(exc),
                )

    def _fetch_model_api_key(
        self,
        access_token: str,
        ed_api_url: str,
        org_id: str,
        user_id: str,
        client_type: str = EAZYBOT_APP_NAME,
    ) -> Optional[str]:
        """用 SSO JWT 调 ED /api/resource/model-api-key/client 获取/创建模型 key。

        密钥不存在则 ED 自动创建（get_or_create）。返回完整的 api_key 字符串；
        网络异常或普通业务失败返回 None；401/403 抛安全领域异常。
        client_type 默认取当前品牌（EAZYBOT_APP_NAME），finbot/eazybot 各自落到对应维度。
        """
        params = urllib.parse.urlencode(
            {
                "org_id": org_id,
                "user_id": user_id,
                "client_type": client_type,
            }
        )
        url = (
            f"{ed_api_url.rstrip('/')}"
            f"/api/resource/model-api-key/client?{params}"
        )
        req = urllib.request.Request(
            url,
            headers={"Authorization": f"Bearer {access_token}"},
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                body = resp.read().decode("utf-8")
                data = json.loads(body)
        except Exception as exc:
            if _is_auth_http_error(exc):
                try:
                    key = OrgSnapshotCache.make_key(
                        ed_api_url, user_id
                    )
                except ValueError:
                    self._invalidate_org_snapshots()
                else:
                    self._invalidate_org_snapshots(key)
                logger.warning(
                    "获取模型 API key 被拒绝: "
                    "reason=authorization_rejected"
                )
                raise ModelKeyAuthorizationError(
                    refresh_allowed=(_auth_http_status(exc) == 401)
                ) from None
            logger.warning(
                "获取模型 API key 失败: reason=%s",
                safe_exception_reason(exc),
            )
            return None

        if not isinstance(data, dict):
            logger.warning("模型 API key 接口返回异常格式: %s", type(data))
            return None

        key = extract_model_api_key(data)
        if "code" not in data and key:
            logger.info("已获取模型 API key: result=found")
            return key

        code = data.get("code", -1)
        if code in (401, 403):
            try:
                key = OrgSnapshotCache.make_key(
                    ed_api_url, user_id
                )
            except ValueError:
                self._invalidate_org_snapshots()
            else:
                self._invalidate_org_snapshots(key)
            logger.warning(
                "模型 API key 接口拒绝鉴权: "
                "reason=authorization_rejected"
            )
            raise ModelKeyAuthorizationError(
                refresh_allowed=(code == 401)
            )
        if code != 0:
            logger.warning(
                "模型 API key 接口返回失败: reason=remote_rejected",
            )
            return None

        if key:
            logger.info("已获取模型 API key: result=found")
            return key
        return None

    def _fetch_model_key_for_profile(
        self, profile_id: str
    ) -> Optional[str]:
        """读取 profile 凭据并获取模型 key，鉴权过期时刷新重试一次。"""
        profile = self._profile_store.get_profile(profile_id)
        if not profile:
            return None
        auth_file = validated_profile_auth_file(
            self._app_root, profile
        )
        if auth_file is None:
            logger.warning(
                "profile 工作目录与账号或团队不匹配，拒绝读取 SSO token"
            )
            return None
        profile_dir = auth_file.parent.parent
        try:
            auth_data, access_token, refresh_token = (
                _read_sso_tokens_from_profile(auth_file)
            )
        except Exception:
            return None
        if not access_token:
            return None

        user_id = str(profile.get("user_id", ""))
        self._require_profile_identity(
            auth_data.get("sso_user_info"), user_id
        )

        ed_api_url = self._pending_ed_api_url or self.get_ed_api_url()
        if not ed_api_url:
            return None

        org_id = profile.get("org_id", "")
        try:
            return self._fetch_model_api_key(
                access_token, ed_api_url, org_id, user_id
            )
        except ModelKeyAuthorizationError as exc:
            if not exc.refresh_allowed or not refresh_token:
                raise

        refreshed_access = ""
        with sso_profile_auth_lock(self._app_root):
            try:
                locked_auth, locked_access, locked_refresh = (
                    _read_sso_tokens_from_profile(auth_file)
                )
            except Exception:
                raise ModelKeyAuthorizationError() from None
            self._require_profile_identity(
                locked_auth.get("sso_user_info"), user_id
            )

            if locked_access and locked_access != access_token:
                refreshed_access = locked_access
            else:
                if not locked_refresh:
                    raise ModelKeyAuthorizationError()
                token_data = refresh_sso_token(locked_refresh)
                if not token_data:
                    try:
                        reloaded, latest_access, _latest_refresh = (
                            _read_sso_tokens_from_profile(auth_file)
                        )
                    except Exception:
                        raise ModelKeyAuthorizationError() from None
                    self._require_profile_identity(
                        reloaded.get("sso_user_info"), user_id
                    )
                    if (
                        not latest_access
                        or latest_access == access_token
                    ):
                        raise ModelKeyAuthorizationError()
                    refreshed_access = latest_access
                else:
                    self._require_profile_identity(
                        token_data.get("user"), user_id
                    )
                    refreshed_access = token_data.get(
                        "access_token", ""
                    )
                    if not refreshed_access:
                        raise ModelKeyAuthorizationError()
                    expires_in = int(token_data.get("expires_in", 0))
                    now = int(time.time())
                    saved = _write_sso_tokens_to_profile(
                        profile_dir,
                        token_data,
                        revive_logged_out=False,
                    )
                    if not saved:
                        raise ModelKeyAuthorizationError()
                    self._profile_store.update_sso_expiry(
                        profile_id,
                        now + expires_in if expires_in else 0,
                        now + _SSO_REFRESH_LIFETIME,
                    )
                    try:
                        sync_sso_tokens_to_sibling_profiles(
                            self._app_root,
                            auth_file,
                            token_data,
                            encrypt_tokens=False,
                            lock_held=True,
                        )
                    except Exception:
                        logger.warning(
                            "模型鉴权刷新后同步兄弟 profile 的 "
                            "SSO token 失败",
                            exc_info=True,
                        )
        return self._fetch_model_api_key(
            refreshed_access, ed_api_url, org_id, user_id
        )

    def switch_profile(self, profile_id: str) -> int:
        """切换 active profile 并重启后端。

        先重启后端，成功后才提交 profiles.json。
        若新 profile 启动失败，回滚到旧 profile。
        """
        if not self._team_switch_enabled:
            raise RuntimeError("团队切换功能未启用")
        if not self._switch_lock.acquire(blocking=False):
            self._switch_state = "busy"
            self._switch_error = "切换进行中，请等待"
            self._switch_seq += 1
            raise RuntimeError("切换进行中，请等待")
        if not self._claim_legacy_operation():
            self._switch_lock.release()
            self._switch_state = "busy"
            self._switch_error = "切换进行中，请等待"
            self._switch_seq += 1
            raise RuntimeError("切换进行中，请等待")
        try:
            self._switch_seq += 1
            self._switch_state = "switching"
            self._switch_error = ""
            logout_epoch = self._logout_epoch
            old_pid = self._current_profile_id

            self._current_profile_id = profile_id
            try:
                port = self.restart_backend()
                if self._logout_epoch != logout_epoch:
                    self._current_profile_id = None
                    raise RuntimeError("已退出登录")
                with team_switch_stage("persist_active_profile"):
                    self._profile_store.activate_profile(profile_id)
            except Exception as exc:
                self._switch_error = str(exc)
                if self._logout_epoch != logout_epoch:
                    self._switch_state = "failed"
                    raise
                logger.warning(
                    "切换目标后端失败，开始回滚: reason=%s",
                    safe_exception_reason(exc),
                )
                self._rollback_profile_switch(old_pid)
                self._switch_state = "failed"
                raise
            if self._logout_epoch != logout_epoch:
                self._switch_state = "failed"
                raise RuntimeError("已退出登录")
            self._switch_state = "success"
            return port
        finally:
            self._release_legacy_operation()
            self._switch_lock.release()

    def _register_backend_start(
        self, expected_logout_epoch: Optional[int]
    ) -> threading.Event:
        """登记可由退出登录取消的后端启动。"""
        cancellation = threading.Event()
        with self._backend_start_lock:
            if (
                expected_logout_epoch is not None
                and self._logout_epoch != expected_logout_epoch
            ):
                cancellation.set()
            self._backend_start_cancellations.add(cancellation)
        return cancellation

    def _unregister_backend_start(
        self, cancellation: threading.Event
    ) -> None:
        """移除已结束的后端启动登记。"""
        with self._backend_start_lock:
            self._backend_start_cancellations.discard(cancellation)

    def start_backend(
        self,
        profile_id: str,
        *,
        expected_logout_epoch: Optional[int] = None,
    ) -> int:
        """通过 Runtime 启动 active slot；健康同 Profile 幂等。"""
        cancellation = self._register_backend_start(
            expected_logout_epoch
        )
        try:
            return self._start_backend_tracked(
                profile_id, cancellation
            )
        finally:
            self._unregister_backend_start(cancellation)

    def _start_backend_tracked(
        self,
        profile_id: str,
        cancellation: threading.Event,
    ) -> int:
        """使用已登记的取消事件启动 active slot。"""
        active = self._backend_runtime.active_slot
        if (
            active is not None
            and active.state is SlotState.ACTIVE
            and active.process.poll() is None
        ):
            if active.identity.profile_id == profile_id:
                return active.port

        try:
            namespace = self._profile_store.ensure_profile_namespace(
                profile_id
            )
        except ProfileNotFoundError:
            raise ValueError(f"profile 不存在: {profile_id}") from None
        profile = self._profile_store.get_profile(profile_id)
        if profile is None:
            raise ValueError(f"profile 不存在: {profile_id}")
        profile["profile_id"] = profile_id
        profile["profile_namespace"] = namespace

        if (
            active is not None
            and active.state is SlotState.ACTIVE
            and active.process.poll() is None
        ):
            raise SlotConflictError("active 槽位仍在运行")

        if active is not None:
            self._backend_runtime.stop_slot(active)

        generation = self._backend_runtime.next_generation()
        slot = self._backend_runtime.start_slot(
            profile,
            operation_id=secrets.token_hex(16),
            generation=generation,
            mode=SlotMode.ACTIVE,
            deadline=SwitchDeadline.after(
                _BACKEND_READY_TIMEOUT,
                clock=self._backend_runtime.clock,
            ),
            cancellation=cancellation,
            initial_handoff_purpose="initial_active",
        )
        self._current_profile_id = profile_id
        self._write_runtime_registry()
        try:
            from ..config.utils import write_last_api

            write_last_api("127.0.0.1", slot.port)
        except Exception:
            logger.warning(
                "回写 last_api 失败，不影响后端就绪",
                exc_info=True,
            )
        logger.info("后端已就绪: port=%s", slot.port)
        return slot.port

    def _prepare_backend_env(
        self,
        profile: dict,
        identity: SlotIdentity,
    ) -> dict[str, str]:
        """在 Popen 前准备 profile-bound env；异常原样交给 Runtime。"""
        self._ensure_lease_heartbeat(identity.profile_namespace)
        with team_switch_stage("fetch_model_key") as stage:
            model_api_key = self._fetch_model_key_for_profile(
                identity.profile_id
            )
            stage.set_result(
                "found" if model_api_key is not None else "missing"
            )
        if model_api_key is None:
            logger.warning(
                "未获取到模型 API key，后端将尝试复用已持久化配置"
            )

        profile_dir = identity.working_dir
        base_env = load_env_chain(self._app_root, profile_dir)
        backend_env = build_backend_env(
            base_env,
            profile_dir,
            str(profile.get("org_id", "")),
            self._app_name,
            self._log_level,
            self._app_root,
            model_api_key=model_api_key,
            handshake_secret=self._handshake_secret,
            user_id=profile.get("user_id", ""),
        )
        env = os.environ.copy()
        env.update(backend_env)
        if self._console_static_server is not None:
            origin = self._console_static_server.origin
            if origin:
                env["EAZYBOT_CORS_ORIGINS"] = _append_cors_origin(
                    env.get("EAZYBOT_CORS_ORIGINS"),
                    origin,
                )
        env.update(
            {
                "EAZYBOT_SHELL_PID": str(os.getpid()),
                "EAZYBOT_SHELL_STARTED_AT": str(self._shell_started_at),
                "EAZYBOT_DESKTOP_LEASE_ID": self._lease_id,
                "EAZYBOT_DESKTOP_RUNTIME_REGISTRY": str(
                    self._runtime_registry.path
                ),
            }
        )
        return env

    def _probe_backend_readiness(
        self,
        host: str,
        port: int,
        remaining: float,
        process: subprocess.Popen,
        slot: BackendSlot,
    ) -> ReadinessResult:
        """active 探活；candidate 必须通过结构化 PREPARE readiness。"""
        started_at = time.monotonic()
        if slot.identity.launch_mode is SlotMode.ACTIVE:
            ready = _wait_for_http(
                host,
                port,
                timeout_sec=remaining,
                proc=process,
            )
            reason = "ready" if ready else "not_ready"
        else:
            ready, reason = self._wait_for_desktop_readiness(
                host,
                port,
                remaining,
                process,
                slot.handshake_secret,
            )
        return ReadinessResult(
            ready=ready,
            reason=reason,
            elapsed_ms=(time.monotonic() - started_at) * 1000,
        )

    @staticmethod
    def _wait_for_desktop_readiness(
        host: str,
        port: int,
        timeout_sec: float,
        process: subprocess.Popen,
        handshake_secret: str,
    ) -> tuple[bool, str]:
        """轮询受握手保护的 candidate readiness，拒绝退化成 healthz。"""
        deadline = time.monotonic() + max(0.0, timeout_sec)
        last_reason = "not_ready"
        url = f"http://{host}:{port}/api/desktop/readiness"
        while time.monotonic() < deadline:
            if process.poll() is not None:
                return False, "process_exited"
            request = urllib.request.Request(
                url,
                headers={
                    "X-EazyBot-Desktop-Handshake": handshake_secret,
                },
            )
            try:
                with urllib.request.urlopen(request, timeout=0.5) as response:
                    payload = json.loads(response.read().decode("utf-8"))
                if payload.get("ready") is True:
                    return True, "ready"
                reason = payload.get("reason")
                if isinstance(reason, str) and reason:
                    last_reason = reason
            except (
                urllib.error.URLError,
                TimeoutError,
                json.JSONDecodeError,
                OSError,
            ):
                last_reason = "readiness_unavailable"
            time.sleep(0.05)
        return False, last_reason

    def stop_backend(self) -> None:
        """停止 Runtime 当前 active slot。"""
        slot = self._backend_runtime.active_slot
        if slot is None:
            return
        logger.info("停止后端子进程...")
        self._backend_runtime.stop_slot(slot)
        self._write_runtime_registry()
        # 端口/fd 审计（P1 诊断手段，不阻塞业务）
        self._audit_fd_and_port(slot.port)

    def shutdown(self) -> None:
        """取消 v2 操作并回收 active/candidate/reaper 全部资源。"""
        self._lease_heartbeat_stop.set()
        heartbeat = self._lease_heartbeat_thread
        if heartbeat is not None and heartbeat is not threading.current_thread():
            heartbeat.join(timeout=2.0)
        self._lease_heartbeat_thread = None
        self._team_switch_coordinator.cancel_current("shutdown")
        self._backend_runtime.stop_all()
        self._backend_runtime.wait_for_reapers(timeout=5.0)
        if self._console_static_server is not None:
            self._console_static_server.stop()
            self._console_static_server = None
        self._release_v2_operation()
        self._runtime_registry.remove()

    def _audit_fd_and_port(self, port: int | None) -> None:
        """teardown 后检查端口占用，异常时记 WARNING。

        不阻塞 v1（仅日志），作为 P1 诊断手段。
        来源：``客户端改造/后端TODO/09-eazybot-壳层-进程管理.md`` §9.7。
        """
        if port is None:
            return
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(0.5)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            in_use = s.connect_ex(("127.0.0.1", port)) == 0
            s.close()
            if in_use:
                logger.warning(
                    "端口审计：port=%s teardown 后仍被占用",
                    port,
                )
                return
        except OSError:
            pass
        try:
            fd_count = len(os.listdir("/proc/self/fd"))
            if fd_count > 120:
                logger.warning(
                    "fd 审计：壳进程 fd_count=%s 偏高",
                    fd_count,
                )
        except OSError:
            pass

    # ── ED 连接探测（09.6）────────────────────────────────────

    def start_ed_probe(self, interval: int = 300) -> None:
        """启动 ED 可达性探测后台线程。

        ``interval`` 默认 300s（5 分钟）。线程 daemon：壳进程退出
        自动回收；仅当 ``get_ed_api_url`` 有值才有探测目标，无则设
        为 optimistic ``online``（ED 未配置场景）。

        若探测线程已在跑（例如退出登录后又重新登录、壳进程未重启），
        改为 set 唤醒事件触发立即重探，而非静默 return——否则
        ``connection_state`` 要挂到下一个 interval 才会重算，登录
        成功后红条仍会多挂最长 5 分钟。
        """
        if self._ed_probe_thread is not None:
            self._ed_probe_wake.set()
            return
        self._ed_probe_thread = threading.Thread(
            target=self._probe_ed_connection,
            args=(interval,),
            daemon=True,
        )
        self._ed_probe_thread.start()
        logger.info(
            "ED 探测线程已启动（间隔 %ss，configured=%s）",
            interval,
            bool(self.get_ed_api_url()),
        )

    def _probe_ed_connection(self, interval: int) -> None:
        """探测循环：可被 ``_ed_probe_wake`` 提前唤醒并立即重探。

        用 ``Event.wait(interval)`` 代替 ``time.sleep``：正常情况下
        等满 interval 后自然醒来；``start_ed_probe`` 在线程已存在时
        调用 ``wake.set()`` 可让其提前返回，不会忙转。醒来后立即
        ``clear()`` 再探测，避免探测期间的新 ``set()`` 被本轮探测
        "免费" 吞掉却又不触发下一轮。
        """
        while True:
            self._ed_probe_wake.wait(interval)
            self._ed_probe_wake.clear()
            try:
                self._probe_ed_once()
            except Exception as exc:
                # 探测线程一旦因未预期异常退出，_ed_probe_thread 仍非
                # None，start_ed_probe() 便只会往死线程上 set 唤醒事件，
                # connection_state 将永久冻结在最后一个值——这正是本次
                # 要修的「状态粘滞」缺陷本身。故此处必须兜住并续跑。
                logger.warning(
                    "ED 探测本轮异常，跳过并继续下一轮: reason=%s",
                    safe_exception_reason(exc),
                )

    def _probe_ed_once(self) -> None:
        """单次 ED 探测：SSO token + health check。"""
        profile = self.get_valid_active_profile()
        # profiles.json 中的 access/refresh 到期时间都不会随后端 token
        # 轮换更新，不能用它们推断 ED 会话失效；这里只确认本地登录凭据仍在。
        if not profile:
            with self._connection_lock:
                self._connection_state = "offline"
            return

        ed_url = self.get_ed_api_url()
        if not ed_url:
            with self._connection_lock:
                self._connection_state = "online"
            return

        try:
            req = urllib.request.Request(
                ed_url.rstrip("/") + "/health",
                method="HEAD",
            )
            resp = urllib.request.urlopen(req, timeout=3)
            resp.close()
            with self._connection_lock:
                self._connection_state = "online"
        except urllib.error.HTTPError as e:
            # HTTP 应答了但状态码非 2xx
            # 4xx = 端点不存在，但 ED 本身可达
            if e.code < 500:
                logger.debug(
                    "ED /health 返回 %d，视为可达",
                    e.code,
                )
                with self._connection_lock:
                    self._connection_state = "online"
            else:
                logger.warning(
                    "ED /health 返回 %d，切换至降级态",
                    e.code,
                )
                with self._connection_lock:
                    self._connection_state = "degraded"
        except (urllib.error.URLError, OSError) as exc:
            logger.warning(
                "ED 探测连接失败: reason=%s",
                safe_exception_reason(exc),
            )
            with self._connection_lock:
                self._connection_state = "degraded"
        except Exception as exc:
            logger.warning(
                "ED 探测未知异常，切换至降级态: reason=%s",
                safe_exception_reason(exc),
            )
            with self._connection_lock:
                self._connection_state = "degraded"

    def _on_backend_exit(
        self,
        slot: BackendSlot,
        code: int,
    ) -> None:
        """只按 watchdog 捕获的不可变 Profile 身份尝试恢复。"""
        if self._team_switch_coordinator.candidate_slot is slot:
            self._team_switch_coordinator.candidate_crashed(
                slot.identity.operation_id,
                slot.identity.generation,
            )
            return
        profile_id = slot.identity.profile_id
        if self._current_profile_id != profile_id:
            return
        restart_epoch = self._logout_epoch
        logger.error("后端子进程意外退出 (code=%s)", code)

        for attempt in range(3):
            time.sleep(2.0)
            if self._current_profile_id != profile_id:
                return
            if self._backend_runtime.active_slot is not None:
                return
            logger.info(
                "后端自动重启 (尝试 %d/3)...",
                attempt + 1,
            )
            try:
                self.start_backend(
                    profile_id,
                    expected_logout_epoch=restart_epoch,
                )
                backend_url = self.backend_url
                if self.on_backend_restarted and backend_url:
                    try:
                        self.on_backend_restarted(backend_url)
                    except Exception as exc:
                        logger.error(
                            "on_backend_restarted 回调失败: reason=%s",
                            safe_exception_reason(exc),
                        )
                return
            except (RuntimeError, ValueError, OSError) as exc:
                logger.error(
                    "后端重启失败 (尝试 %d/3): reason=%s",
                    attempt + 1,
                    safe_exception_reason(exc),
                )

        logger.error("后端重启失败，已达最大重试次数")

    def restart_backend(self) -> int:
        """重启后端子进程（重载新 token/env）。"""
        # RLock 可重入：switch_profile 持锁后调本方法不会死锁
        if not self._switch_lock.acquire(blocking=False):
            raise RuntimeError("操作进行中，请等待")
        if not self._claim_legacy_operation():
            self._switch_lock.release()
            raise RuntimeError("操作进行中，请等待")
        try:
            pid = self._current_profile_id
            with team_switch_stage("stop_backend"):
                self.stop_backend()
            if pid is None:
                raise RuntimeError("无当前 profile，无法重启")
            return self.start_backend(pid)
        finally:
            self._release_legacy_operation()
            self._switch_lock.release()

    def on_sso_expired(self) -> str:
        """bridge：token 过期重登。

        停后端 -> SSO 重登 -> 换 token -> 写回 auth.json -> 重启后端。
        返回 ``ok``、``busy``、``superseded`` 或 ``failed``。

        本方法阻塞（SSO 登录最长 5 分钟），bridge 层应在 worker
        线程调用。
        """
        epoch = self._logout_epoch

        def _result(status: str) -> str:
            return "superseded" if self._logout_epoch != epoch else status

        self._invalidate_org_snapshots()
        if not self._switch_lock.acquire(blocking=False):
            logger.warning("on_sso_expired: 操作进行中，跳过")
            return "busy"
        if not self._claim_legacy_operation():
            self._switch_lock.release()
            logger.warning("on_sso_expired: v2 切换进行中，跳过")
            return "busy"
        try:
            if self._logout_epoch != epoch:
                return "superseded"
            _now_ts = time.time()
            _cooldown_left = _now_ts - _last_sso_login_success_ts
            if _cooldown_left < _SSO_RELOGIN_COOLDOWN_SECONDS:
                logger.warning("on_sso_expired: 冷却期内，跳过重登")
                return "busy"
            ed_sso_url = self.get_ed_sso_url()
            if not ed_sso_url:
                logger.error("无法重登：EAZYDEVELOP_SSO_URL 未设置")
                return _result("failed")

            self.stop_backend()

            ott = start_sso_login(ed_sso_url)
            if not ott:
                return _result("failed")

            token_data = exchange_sso_token(ott)
            if "error" in token_data:
                logger.error(
                    "重登 token 交换失败: reason=remote_rejected"
                )
                return _result("failed")

            profile = self._profile_store.get_profile(
                self._current_profile_id
            )
            if profile is None:
                logger.error("无法写回 token：无当前 profile")
                return _result("failed")

            try:
                self._require_profile_identity(
                    token_data.get("user"),
                    str(profile.get("user_id", "")),
                )
            except ProfileIdentityMismatchError:
                logger.warning(
                    "重登身份与当前 Profile 不一致，拒绝写回 token"
                )
                return _result("failed")

            if self._logout_epoch != epoch:
                return "superseded"

            auth_file = validated_profile_auth_file(
                self._app_root, profile
            )
            if auth_file is None:
                logger.error("无法写回 token：Profile 工作目录无效")
                return _result("failed")
            profile_dir = auth_file.parent.parent
            _write_sso_tokens_to_profile(profile_dir, token_data)
            try:
                sync_sso_tokens_to_sibling_profiles(
                    self._app_root,
                    auth_file,
                    token_data,
                    encrypt_tokens=False,
                )
            except Exception:
                logger.warning(
                    "重登后同步兄弟 profile 的 SSO token 失败",
                    exc_info=True,
                )

            expires_in = int(token_data.get("expires_in", 0))
            now = int(time.time())
            access_expires = now + expires_in if expires_in else 0
            refresh_expires = now + _SSO_REFRESH_LIFETIME
            self._profile_store.update_sso_expiry(
                self._current_profile_id,
                access_expires,
                refresh_expires,
            )

            try:
                self.start_backend(self._current_profile_id)
            except Exception as exc:
                logger.error(
                    "重启后端失败: reason=%s",
                    safe_exception_reason(exc),
                )
                return _result("failed")

            if self._logout_epoch != epoch:
                self.stop_backend()
                self._current_profile_id = None
                return "superseded"
            return "ok"
        finally:
            self._release_legacy_operation()
            self._switch_lock.release()

    def on_logout(self) -> None:
        """bridge：退出登录。

        停后端 -> 清当前 profile 的 SSO token -> 更新 profiles.json。
        UI 层负责回壳原生登录页。
        """
        with self._backend_start_lock:
            self._logout_epoch += 1
            for cancellation in self._backend_start_cancellations:
                cancellation.set()
        self._invalidate_org_snapshots()
        cancel_sso_login()
        try:
            acquired = self._switch_lock.acquire(
                timeout=_LOGOUT_LOCK_TIMEOUT
            )
        except TypeError:
            # 兼容测试替身和旧锁实现；生产 RLock 仍采用 15 秒上限。
            acquired = self._switch_lock.acquire()
        claimed = False
        try:
            self._pending_orgs = []
            self._pending_token_data = None
            self._pending_user_info = None
            self._login_seq += 1
            self._login_state = "idle"
            self._login_error = ""
            if acquired:
                claimed = self._claim_legacy_operation()
            profile = self._profile_store.get_profile(
                self._current_profile_id
            )
            if profile is None:
                return

            self.stop_backend()
            auth_file = validated_profile_auth_file(
                self._app_root, profile
            )
            with sso_profile_auth_lock(self._app_root):
                if auth_file is None:
                    logger.error("退出登录时 Profile 工作目录无效")
                else:
                    profile_dir = auth_file.parent.parent
                    _clear_sso_tokens(profile_dir)
                self._profile_store.update_sso_expiry(
                    self._current_profile_id, 0, 0
                )

            self._current_profile_id = None
            logger.info("已退出登录")
        finally:
            if claimed:
                self._release_legacy_operation()
            if acquired:
                self._switch_lock.release()

    def delete_profile(self, profile_id: str) -> None:
        """删除 profile。若为 active 则先停后端。"""
        if not self._switch_lock.acquire(blocking=False):
            raise RuntimeError("操作进行中，请等待")
        if not self._claim_legacy_operation():
            self._switch_lock.release()
            raise RuntimeError("操作进行中，请等待")
        try:
            if profile_id == self._current_profile_id:
                self.stop_backend()
                self._current_profile_id = None
            delete_profile_entry(
                self._profile_store, self._app_root, profile_id
            )
        finally:
            self._release_legacy_operation()
            self._switch_lock.release()

    def cleanup_legacy(self) -> None:
        """首启老数据迁移清理。"""
        cleanup_legacy_data(self._app_root)

    def cleanup_stale_provisionals(self) -> None:
        """锁后把崩溃候选移入恢复区，再移除其索引。"""
        stale = self._profile_store.list_stale_provisionals(set())
        if not stale:
            return
        ready_dirs = {
            Path(profile["working_dir"]).expanduser().resolve()
            for profile in self._profile_store.list_profiles()
            if isinstance(profile.get("working_dir"), str)
        }
        recovered = 0
        rejected = 0
        for profile in stale:
            if self._recover_stale_provisional(profile, ready_dirs):
                recovered += 1
            else:
                rejected += 1
        if recovered:
            logger.info(
                "已保存并清理崩溃遗留的候选 Profile: count=%d",
                recovered,
            )
        if rejected:
            logger.warning(
                "候选 Profile 恢复校验未通过，已保留原数据: count=%d",
                rejected,
            )

    def _recover_stale_provisional(
        self,
        profile: dict,
        ready_dirs: set[Path],
    ) -> bool:
        """安全保存一个候选目录；失败时保留目录和索引。"""
        user_id = profile.get("user_id")
        org_id = profile.get("org_id")
        owner = profile.get("provisioning_operation_id")
        working_dir = profile.get("working_dir")
        if not all(
            isinstance(value, str) and value
            for value in (user_id, org_id, owner, working_dir)
        ):
            return False
        profiles_root = (self._app_root / "profiles").resolve()
        expected = _profile_dir(
            self._app_root, user_id, org_id
        ).resolve()
        source = Path(working_dir).expanduser().resolve()
        if (
            source != expected
            or not expected.is_relative_to(profiles_root)
            or source in ready_dirs
            or source.is_symlink()
            or (source.exists() and not source.is_dir())
        ):
            return False

        profile_id = ProfileStore.make_profile_id(user_id, org_id)
        recovery_item: Path | None = None
        moved = False
        if source.exists():
            recovery_root = self._app_root / _PROVISIONAL_RECOVERY_DIR
            recovery_root.mkdir(mode=0o700, parents=True, exist_ok=True)
            os.chmod(recovery_root, 0o700)
            recovery_item = recovery_root / secrets.token_hex(16)
            recovery_item.mkdir(mode=0o700)
            manifest = recovery_item / "manifest.json"
            manifest.write_text(
                json.dumps(
                    {
                        "version": 1,
                        "profile_id": profile_id,
                        "working_dir": str(expected),
                        "recovered_at": int(time.time()),
                    },
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
            os.chmod(manifest, 0o600)
            try:
                os.replace(source, recovery_item / "workspace")
                moved = True
            except OSError:
                shutil.rmtree(recovery_item, ignore_errors=True)
                return False

        if self._profile_store.discard_provisional(profile_id, owner):
            return True

        if moved and recovery_item is not None and not source.exists():
            try:
                source.parent.mkdir(parents=True, exist_ok=True)
                os.replace(recovery_item / "workspace", source)
                shutil.rmtree(recovery_item, ignore_errors=True)
            except OSError:
                logger.error("候选 Profile 索引清理失败，目录恢复也失败")
        return False

    def _restore_recovered_provisional(
        self,
        profile_id: str,
        target_dir: Path,
    ) -> bool:
        """同团队重试时显式恢复最近一次候选工作区。"""
        target = target_dir.expanduser().resolve()
        profiles_root = (self._app_root / "profiles").resolve()
        if target.exists() or not target.is_relative_to(profiles_root):
            return False
        recovery_root = self._app_root / _PROVISIONAL_RECOVERY_DIR
        if not recovery_root.is_dir():
            return False
        manifests = sorted(
            recovery_root.glob("*/manifest.json"),
            key=lambda path: path.stat().st_mtime,
            reverse=True,
        )
        for manifest in manifests:
            try:
                data = json.loads(manifest.read_text(encoding="utf-8"))
                workspace = manifest.parent / "workspace"
                if (
                    data.get("version") != 1
                    or data.get("profile_id") != profile_id
                    or Path(data.get("working_dir", "")).resolve()
                    != target
                    or not workspace.is_dir()
                    or workspace.is_symlink()
                ):
                    continue
                target.parent.mkdir(parents=True, exist_ok=True)
                os.replace(workspace, target)
                manifest.unlink()
                manifest.parent.rmdir()
                try:
                    recovery_root.rmdir()
                except OSError:
                    pass
                logger.info("已复用崩溃前保存的候选 Profile 工作区")
                return True
            except (OSError, ValueError, TypeError, json.JSONDecodeError):
                continue
        return False
